insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('de000000-0000-0000-0000-000000000001', 'mrcp2', '288977be-2bc0-4daf-a1f4-31937c4b3262',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('de000000-0000-0000-0000-000000000001', 'A', 'Mepolizumab (anti-IL-5 monoclonal antibody)', true, 'Correct. Mepolizumab targets IL-5, reducing eosinophil production and survival, and is licensed for severe eosinophilic asthma with blood eosinophils ≥300 cells/microlitre and recurrent exacerbations despite optimised inhaled therapy. Her eosinophil count and exacerbation history meet criteria, and her IgE is too low for omalizumab.', 1),
('de000000-0000-0000-0000-000000000001', 'B', 'Omalizumab (anti-IgE monoclonal antibody)', false, 'Ruled out because omalizumab requires a raised total IgE within a specific dosing range and evidence of perennial allergen sensitisation; her IgE of 45 IU/mL is too low to qualify, and her phenotype is eosinophil-driven rather than allergic/IgE-driven.', 2),
('de000000-0000-0000-0000-000000000001', 'C', 'Increase inhaled corticosteroid to the maximum licensed dose and reassess in 3 months without a biologic', false, 'Ruled out because she is already on high-dose ICS/LABA/LAMA with ongoing exacerbations and a clear eosinophilic biomarker profile; further dose escalation without addressing the underlying eosinophilic inflammation is unlikely to achieve control and delays appropriate biologic therapy.', 3),
('de000000-0000-0000-0000-000000000001', 'D', 'Start maintenance oral prednisolone 10 mg daily long-term', false, 'Ruled out because long-term oral corticosteroids carry substantial cumulative toxicity (osteoporosis, diabetes, adrenal suppression, cataracts) and should be avoided when a targeted biologic can address the same eosinophilic pathway with a far better safety profile.', 4),
('de000000-0000-0000-0000-000000000001', 'E', 'Refer for bronchial thermoplasty as first-line add-on therapy', false, 'Ruled out because bronchial thermoplasty is not first-line; biologic therapy should be trialled first in patients with a clear eosinophilic phenotype meeting biologic eligibility criteria, with thermoplasty reserved for selected patients who remain uncontrolled despite biologics.', 5),
('de000000-0000-0000-0000-000000000002', 'A', 'Start azithromycin 250 mg three times weekly as first-line, without checking baseline ECG or liver function', false, 'Ruled out because prophylactic azithromycin is a reasonable option in frequent exacerbators (particularly non-smokers) but requires baseline ECG (QT interval), liver function tests, and sputum culture to exclude atypical mycobacteria before starting, given risks of QT prolongation and antimicrobial resistance.', 1),
('de000000-0000-0000-0000-000000000002', 'B', 'Add regular oral prednisolone 5 mg daily as maintenance therapy', false, 'Ruled out because maintenance oral corticosteroids are not recommended in COPD due to significant long-term toxicity without proven mortality or robust exacerbation benefit; they should be reserved for acute exacerbations only.', 2),
('de000000-0000-0000-0000-000000000002', 'C', 'Stop the inhaled corticosteroid component given his eosinophilia is expected to fall with ICS withdrawal, reducing pneumonia risk', false, 'Ruled out because his high eosinophil count and exacerbation frequency actually predict a good response to ICS, and withdrawing ICS in a frequently exacerbating, ICS-responsive eosinophilic phenotype increases exacerbation risk.', 3),
('de000000-0000-0000-0000-000000000002', 'D', 'Refer for lung volume reduction surgery as the next step', false, 'Ruled out because lung volume reduction surgery targets specific hyperinflated emphysematous phenotypes with resistant breathlessness, not primarily exacerbation frequency, and is not indicated here based on the information given.', 4),
('de000000-0000-0000-0000-000000000002', 'E', 'Add-on biologic therapy is not routinely available for COPD; optimise triple inhaler technique and consider referral for pulmonary rehabilitation, with roflumilast considered given his eosinophilia and exacerbation phenotype', true, 'Correct. In frequent exacerbators already on maximal triple inhaled therapy with a raised eosinophil count, roflumilast (a PDE4 inhibitor) reduces exacerbations in patients with a chronic bronchitis phenotype and eosinophilia, though the evidence base is more classically for chronic bronchitis with cough/sputum. Pulmonary rehabilitation and confirming inhaler technique/adherence are essential first steps in any exacerbation-prone patient before or alongside pharmacological escalation.', 5),
('de000000-0000-0000-0000-000000000003', 'A', 'Life-threatening asthma', false, $x$Ruled out because life-threatening features require PEF <33%, oxygen saturation <92%, silent chest, cyanosis, poor respiratory effort, arrhythmia, hypotension, exhaustion, confusion, or a normal/raised pCO2 in the context of severe distress; her pCO2 of 4.6 kPa, while relatively high for a hyperventilating asthmatic, is not clearly in the 'normalising/rising' danger range described with other life-threatening features, and her PEF is 45%, not <33%.$x$, 1),
('de000000-0000-0000-0000-000000000003', 'B', 'Acute severe asthma', true, 'Correct. Acute severe asthma is defined by any one of: PEF 33-50% of best/predicted, respiratory rate ≥25/min, heart rate ≥110/min, or inability to complete sentences in one breath. Her PEF of 45%, respiratory rate 28, and heart rate 118 all meet acute severe criteria; a near-normal pCO2 in an asthmatic tachypnoeic patient is itself a warning sign of tiring but her PEF/RR/HR place her in the severe (not yet life-threatening) category as no life-threatening features are present.', 2),
('de000000-0000-0000-0000-000000000003', 'C', 'Moderate asthma exacerbation', false, 'Ruled out because moderate asthma is characterised by increasing symptoms with PEF >50-75% best/predicted and no features of acute severe asthma; her PEF of 45% and tachycardia/tachypnoea exceed this category.', 3),
('de000000-0000-0000-0000-000000000003', 'D', 'Near-fatal asthma', false, 'Ruled out because near-fatal asthma is defined by a raised pCO2 requiring mechanical ventilation with raised inflation pressures; there is no evidence of hypercapnic respiratory failure or ventilatory support requirement here.', 4),
('de000000-0000-0000-0000-000000000003', 'E', 'Brittle asthma', false, 'Ruled out because brittle asthma describes a pattern of recurrent severe attacks with normal or near-normal lung function between episodes (or persistent variability despite high-dose therapy), not a single acute severity classification for this presentation.', 5),
('de000000-0000-0000-0000-000000000004', 'A', 'IV amphotericin B as first-line antifungal therapy', false, 'Ruled out because ABPA is an immune hypersensitivity reaction to Aspergillus colonisation, not invasive fungal infection; IV amphotericin B is reserved for invasive aspergillosis, not ABPA, and would not address the underlying hypersensitivity mechanism.', 1),
('de000000-0000-0000-0000-000000000004', 'B', 'Omalizumab as first-line monotherapy without corticosteroids', false, 'Ruled out because although omalizumab has a role in refractory or corticosteroid-dependent ABPA, first-line treatment remains oral corticosteroids; omalizumab is generally reserved for cases requiring steroid-sparing strategies after initial treatment, not as untried monotherapy from the outset.', 2),
('de000000-0000-0000-0000-000000000004', 'C', 'Oral corticosteroids (e.g. prednisolone), tapered over several weeks, with consideration of itraconazole as a steroid-sparing agent', true, 'Correct. This presentation (asthma, central bronchiectasis, markedly raised total IgE, peripheral eosinophilia, Aspergillus sensitisation with brown mucus plugs) is classic for allergic bronchopulmonary aspergillosis (ABPA). First-line treatment is oral corticosteroids to suppress the immune-mediated inflammatory response, with itraconazole often added as a steroid-sparing agent to reduce fungal antigenic burden and allow steroid dose reduction.', 3),
('de000000-0000-0000-0000-000000000004', 'D', 'Surgical resection of the bronchiectatic lung segments', false, 'Ruled out because ABPA is a diffuse immunological process; surgery is not indicated as initial management and would not address the underlying hypersensitivity driving ongoing lung damage.', 4),
('de000000-0000-0000-0000-000000000004', 'E', 'Reassurance and no specific treatment, as bronchiectasis in asthma is an incidental finding not requiring intervention', false, 'Ruled out because untreated ABPA leads to progressive bronchiectasis and lung fibrosis; the combination of markedly raised IgE, eosinophilia, and Aspergillus sensitisation with mucus plugging requires active treatment, not observation.', 5),
('de000000-0000-0000-0000-000000000005', 'A', 'Long-term home mechanical ventilation with nocturnal NIV', false, 'Ruled out because home NIV in COPD is primarily indicated for chronic hypercapnic respiratory failure, not simply for severe breathlessness from hyperinflation without evidence of hypercapnia given in this vignette.', 1),
('de000000-0000-0000-0000-000000000005', 'B', 'Single lung transplantation as the immediate next step, bypassing less invasive options', false, 'Ruled out because less invasive bronchoscopic lung volume reduction should be considered first in a suitable candidate with heterogeneous emphysema and no collateral ventilation; transplantation carries significant risk and is reserved for those who fail other therapies or are otherwise not candidates for bronchoscopic intervention.', 2),
('de000000-0000-0000-0000-000000000005', 'C', 'Continuous long-term oxygen therapy alone, without further intervention', false, 'Ruled out because long-term oxygen therapy is indicated for chronic hypoxaemia (not stated here) and does not address the mechanical hyperinflation driving his breathlessness; it would not be expected to provide the same symptomatic benefit as volume reduction in this candidate.', 3),
('de000000-0000-0000-0000-000000000005', 'D', 'Endobronchial valve insertion for bronchoscopic lung volume reduction', true, 'Correct. In patients with severe hyperinflation from heterogeneous emphysema, intact fissures (indicating absence of collateral ventilation between lobes), and confirmed absence of collateral ventilation on Chartis assessment, endobronchial valve placement can achieve targeted lobar volume reduction, improving lung mechanics, breathlessness, and exercise capacity with a less invasive approach than surgery.', 4),
('de000000-0000-0000-0000-000000000005', 'E', 'Surgical lung volume reduction as first-line, given equivalent efficacy to bronchoscopic valves', false, 'Ruled out because in a patient who is anatomically suitable for the less invasive endobronchial valve approach (heterogeneous emphysema, intact fissures, no collateral ventilation), bronchoscopic valve placement is preferred first-line over surgery due to lower morbidity, with surgery reserved for those unsuitable for or who fail valve therapy.', 5),
('de000000-0000-0000-0000-000000000006', 'A', 'Poorly controlled eosinophilic asthma requiring biologic therapy', false, 'Ruled out because true asthma typically shows a flattened expiratory limb only (variable intrathoracic obstruction) rather than flattening of both limbs, and the episodic stridor with rapid resolution is atypical for asthma; escalating asthma therapy has already failed, prompting reconsideration of the diagnosis.', 1),
('de000000-0000-0000-0000-000000000006', 'B', 'Tracheomalacia', false, $x$Ruled out because tracheomalacia classically causes expiratory flow limitation and can cause a 'sawtooth' pattern or expiratory collapse on dynamic imaging/bronchoscopy, but the episodic, rapidly resolving stridor with symptom-free intervals is more typical of inducible laryngeal obstruction than fixed tracheal wall weakness.$x$, 2),
('de000000-0000-0000-0000-000000000006', 'C', 'Bronchiolitis obliterans', false, 'Ruled out because bronchiolitis obliterans causes fixed, progressive airflow obstruction typically following lung transplant, connective tissue disease, or toxic inhalation, not episodic symptoms that resolve completely between attacks.', 3),
('de000000-0000-0000-0000-000000000006', 'D', 'Inducible laryngeal obstruction (vocal cord dysfunction)', true, 'Correct. The flattened inspiratory AND expiratory limbs on the flow-volume loop (suggesting a variable extrathoracic obstruction), episodic stridor, rapid onset/offset of symptoms, poor response to escalating asthma therapy, and triggers like exercise are characteristic of inducible laryngeal obstruction, a common asthma mimic/co-existing condition caused by paradoxical vocal cord adduction. Diagnosis is confirmed by laryngoscopy during symptomatic episodes.', 4),
('de000000-0000-0000-0000-000000000006', 'E', 'Cardiac-related exertional dyspnoea (e.g. undiagnosed heart failure)', false, 'Ruled out because the flow-volume loop findings and episodic stridor point specifically to an upper airway/laryngeal process rather than a cardiac cause, and there is no supporting history of cardiac disease.', 5),
('de000000-0000-0000-0000-000000000007', 'A', 'This is an expected pharmacological effect of benralizumab (near-complete eosinophil depletion via antibody-dependent cell cytotoxicity); continue treatment as planned', true, 'Correct. Benralizumab binds the IL-5 receptor alpha subunit and induces near-complete depletion of eosinophils via antibody-dependent cell-mediated cytotoxicity (unlike mepolizumab/reslizumab, which reduce but do not eliminate eosinophils by blocking IL-5 itself). A near-zero eosinophil count is the expected, desired pharmacodynamic effect and is not itself a reason for concern or treatment change, given he remains clinically well.', 1),
('de000000-0000-0000-0000-000000000007', 'B', 'This indicates a false-positive severe asthma diagnosis and biologic therapy should be stopped', false, 'Ruled out because eosinophil depletion on benralizumab is a pharmacological effect of the drug, not evidence that the original diagnosis was incorrect; stopping an effective treatment based on this finding would be inappropriate.', 2),
('de000000-0000-0000-0000-000000000007', 'C', 'This suggests he has developed a secondary immunodeficiency and needs immunoglobulin replacement', false, 'Ruled out because isolated eosinophil depletion from anti-IL-5 receptor therapy does not cause a global immunodeficiency requiring immunoglobulin replacement; eosinophils are not central to humoral immunity in this way.', 3),
('de000000-0000-0000-0000-000000000007', 'D', 'Benralizumab should be switched to mepolizumab because eosinophil depletion is a sign of drug toxicity', false, 'Ruled out because eosinophil depletion is not toxicity but the intended mechanism of action; switching biologics is unnecessary when the patient is responding well clinically.', 4),
('de000000-0000-0000-0000-000000000007', 'E', 'Urgent bone marrow biopsy is required to investigate for an underlying myeloid disorder', false, 'Ruled out because the eosinopenia is fully explained by his known medication (benralizumab) and expected mechanism of action; invasive investigation is not warranted without other concerning features.', 5),
('de000000-0000-0000-0000-000000000008', 'A', 'Combination prednisolone, azathioprine, and N-acetylcysteine triple therapy', false, 'Ruled out because the PANTHER-IPF trial showed this combination increased mortality and hospitalisation in IPF and is now contraindicated; IPF is not primarily an inflammatory/immunosuppressant-responsive disease in the way some other ILDs are.', 1),
('de000000-0000-0000-0000-000000000008', 'B', 'High-dose inhaled corticosteroids alone', false, 'Ruled out because IPF does not have a significant inflammatory component that responds to corticosteroids, and inhaled corticosteroids have no evidence base for altering the fibrotic disease course.', 2),
('de000000-0000-0000-0000-000000000008', 'C', 'Long-term low-dose oral corticosteroid monotherapy', false, 'Ruled out because corticosteroid monotherapy has not been shown to alter the natural history of IPF and exposes the patient to steroid toxicity without proven disease-modifying benefit.', 3),
('de000000-0000-0000-0000-000000000008', 'D', 'Watchful waiting with no pharmacological therapy until FVC falls below 50% predicted', false, 'Ruled out because current guidelines recommend considering antifibrotic therapy at diagnosis in patients with mild-to-moderate IPF, given evidence that earlier treatment preserves lung function, rather than delaying until advanced decline.', 4),
('de000000-0000-0000-0000-000000000008', 'E', 'Antifibrotic therapy with either pirfenidone or nintedanib', true, 'Correct. Both pirfenidone (an antifibrotic/anti-inflammatory agent) and nintedanib (a tyrosine kinase inhibitor targeting fibrogenic growth factor pathways) have been shown in randomised trials (ASCEND/CAPACITY for pirfenidone, INPULSIS for nintedanib) to significantly slow the annual rate of FVC decline in IPF and are recommended for patients with mild-to-moderate disease such as this.', 5),
('de000000-0000-0000-0000-000000000009', 'A', 'Increase mycophenolate dose and reassess again in 12 months without other changes', false, 'Ruled out because she has already shown significant progression on her current immunosuppressive regimen; simply increasing the same drug without addressing the fibrotic component (via an antifibrotic) is unlikely to be effective and delays evidence-based intervention for progressive fibrosis.', 1),
('de000000-0000-0000-0000-000000000009', 'B', 'Add nintedanib for progressive pulmonary fibrosis', true, 'Correct. This patient meets criteria for progressive pulmonary fibrosis (PPF) — a UIP-pattern fibrosing ILD with clinically significant decline (relative FVC decline ≥10% is diagnostic; smaller declines with worsening symptoms/DLCO also qualify) despite standard management. The INBUILD trial demonstrated nintedanib slows FVC decline in progressive fibrosing ILD of any underlying cause, including connective tissue disease-associated ILD, and is licensed as an add-on to ongoing immunosuppression in this context.', 2),
('de000000-0000-0000-0000-000000000009', 'C', 'Switch to high-dose oral corticosteroids as monotherapy', false, 'Ruled out because corticosteroid monotherapy has not been shown to benefit progressive fibrotic ILD once fibrosis (traction bronchiectasis, honeycombing) has developed, and prolonged high-dose steroids carry significant toxicity without proven benefit for the fibrotic component.', 3),
('de000000-0000-0000-0000-000000000009', 'D', 'List for lung transplantation immediately without trialling antifibrotic therapy', false, 'Ruled out because antifibrotic therapy (nintedanib) should be trialled to slow progression before proceeding directly to transplant assessment, although early transplant referral/discussion is reasonable to run in parallel given her trajectory.', 4),
('de000000-0000-0000-0000-000000000009', 'E', 'Stop all immunosuppression as it may be worsening lung fibrosis', false, 'Ruled out because immunosuppression remains important for her underlying rheumatoid arthritis and inflammatory ILD component; nintedanib is added to, not substituted for, ongoing appropriate immunosuppressive therapy in CTD-ILD.', 5),
('de000000-0000-0000-0000-000000000010', 'A', 'Start pirfenidone immediately as first-line disease-modifying therapy', false, 'Ruled out because pirfenidone is licensed for IPF, not non-fibrotic hypersensitivity pneumonitis; antigen avoidance and, if needed, corticosteroids/immunosuppression are the primary treatments for HP, with antifibrotics reserved for cases that have progressed to a fibrotic phenotype.', 1),
('de000000-0000-0000-0000-000000000010', 'B', 'Reassure him that pigeon exposure is unrelated as precipitins are commonly falsely positive', false, $x$Ruled out because in the context of a compatible clinical and radiological picture, positive avian precipitins support (rather than are dismissed from) the diagnosis of bird fancier's lung, and ongoing exposure is a proven driver of disease progression.$x$, 2),
('de000000-0000-0000-0000-000000000010', 'C', 'Complete avoidance of avian antigen exposure (removal of birds/pigeon lofts from his environment)', true, $x$Correct. The history (bird exposure), HRCT findings (ground-glass change, mosaic attenuation/air trapping, centrilobular nodules), and positive avian precipitins are consistent with hypersensitivity pneumonitis (bird fancier's lung). The single most important intervention is complete and ongoing antigen avoidance, as continued exposure drives ongoing inflammation and risk of progression to fibrotic disease; without avoidance, pharmacological treatment is far less effective.$x$, 3),
('de000000-0000-0000-0000-000000000010', 'D', 'Commence long-term oral corticosteroids without addressing ongoing antigen exposure', false, 'Ruled out because corticosteroids may have a role in symptomatic or progressive HP, but starting them while ongoing antigen exposure continues is far less effective, and without antigen avoidance the disease is likely to progress or relapse despite treatment.', 4),
('de000000-0000-0000-0000-000000000010', 'E', 'Arrange lung transplantation assessment as the primary next step', false, 'Ruled out because this is a potentially reversible, non-fibrotic (or early) presentation where antigen avoidance is the priority; transplantation would only be considered for irreversible, end-stage fibrotic disease unresponsive to avoidance and medical therapy.', 5),
('de000000-0000-0000-0000-000000000011', 'A', 'Discontinue nintedanib permanently at the first report of diarrhoea', false, 'Ruled out because mild-to-moderate diarrhoea on nintedanib is common and usually manageable with anti-diarrhoeal treatment and dose adjustment; permanent discontinuation at the first symptom would deprive him of a disease-modifying therapy unnecessarily when simpler measures are available first.', 1),
('de000000-0000-0000-0000-000000000011', 'B', 'Switch immediately to pirfenidone without trialling symptomatic management of the diarrhoea', false, 'Ruled out because the initial approach to nintedanib-associated diarrhoea is symptomatic treatment (loperamide) and dose modification if needed, not an immediate switch to an alternative antifibrotic before these measures have been tried.', 2),
('de000000-0000-0000-0000-000000000011', 'C', 'Continue nintedanib unchanged and arrange colonoscopy to investigate for a new primary bowel pathology', false, 'Ruled out because in a patient recently started on nintedanib with no alarm features (rectal bleeding, anaemia) described, the diarrhoea is most likely drug-related; simple management of the known adverse effect is appropriate before invasive investigation for an unrelated cause.', 3),
('de000000-0000-0000-0000-000000000011', 'D', 'Add loop diuretic therapy to manage fluid loss from diarrhoea', false, 'Ruled out because loop diuretics would exacerbate rather than treat fluid/electrolyte losses from diarrhoea and have no role in managing this adverse effect.', 4),
('de000000-0000-0000-0000-000000000011', 'E', 'Initiate loperamide for symptomatic control and continue nintedanib at the current dose if diarrhoea improves; reduce the dose if it persists or is severe', true, 'Correct. Diarrhoea is the most common adverse effect of nintedanib, occurring in the majority of patients, and is usually managed with prompt introduction of anti-diarrhoeal agents such as loperamide, adequate hydration, and dietary modification, allowing continuation at full dose in many cases. If diarrhoea persists despite this or becomes severe, dose reduction (e.g. to 100 mg twice daily) or temporary interruption is the next step before considering discontinuation, rather than stopping the drug immediately.', 5),
('de000000-0000-0000-0000-000000000012', 'A', 'Observation with regular clinical and spirometric follow-up, without starting corticosteroids', true, 'Correct. Stage II pulmonary sarcoidosis with minimal symptoms, normal spirometry, and no evidence of extrapulmonary organ involvement (cardiac, neurological, ocular) has a high rate of spontaneous resolution. Current guidelines recommend observation with regular follow-up (clinical assessment, spirometry, imaging) rather than immediate corticosteroid treatment, reserving treatment for significant, progressive, or organ/life-threatening disease.', 1),
('de000000-0000-0000-0000-000000000012', 'B', 'Start high-dose oral corticosteroids immediately given radiographic lymphadenopathy', false, 'Ruled out because asymptomatic or mildly symptomatic sarcoidosis with preserved lung function and no critical organ involvement does not require immediate treatment; corticosteroids carry significant toxicity and should be reserved for progressive, symptomatic, or organ-threatening disease.', 2),
('de000000-0000-0000-0000-000000000012', 'C', 'Commence methotrexate as first-line steroid-sparing therapy', false, 'Ruled out because methotrexate is typically used as a second-line, steroid-sparing agent in patients who require ongoing treatment or who cannot tolerate/wean corticosteroids, not as first-line therapy in an asymptomatic patient who does not yet need treatment.', 3),
('de000000-0000-0000-0000-000000000012', 'D', 'Arrange mediastinal lymph node excision for further diagnostic clarity', false, 'Ruled out because the diagnosis has already been confirmed histologically (non-caseating granulomas with negative infective cultures) via EBUS biopsy; further surgical excision is unnecessary and would not change management.', 4),
('de000000-0000-0000-0000-000000000012', 'E', 'Start anti-tuberculous therapy empirically given granulomatous inflammation', false, 'Ruled out because mycobacterial cultures are negative and the clinical/radiological picture (bilateral symmetrical hilar lymphadenopathy, non-caseating granulomas) is classic for sarcoidosis rather than tuberculosis; empirical anti-TB therapy is not indicated without supporting evidence.', 5),
('de000000-0000-0000-0000-000000000013', 'A', 'Start mycophenolate mofetil immediately in all patients with any HRCT abnormality regardless of extent or trajectory', false, 'Ruled out because treatment decisions in SSc-ILD are guided by disease extent, functional impairment, and evidence of progression, not by the mere presence of any HRCT abnormality; treating all patients regardless of risk would over-treat a substantial proportion who would remain stable.', 1),
('de000000-0000-0000-0000-000000000013', 'B', 'Surveillance with serial pulmonary function tests and clinical review, reserving immunosuppression/antifibrotic therapy for evidence of progression', true, 'Correct. Systemic sclerosis-associated ILD with limited extent on HRCT (<10-20% involvement), preserved lung function, and no symptoms carries a lower risk of significant progression; a reasonable approach is close surveillance (serial PFTs, HRCT as indicated) with treatment reserved for those who show physiological or radiological progression, avoiding unnecessary exposure to immunosuppressant or antifibrotic toxicity in low-risk limited disease.', 2),
('de000000-0000-0000-0000-000000000013', 'C', 'Arrange immediate lung transplantation work-up', false, 'Ruled out because her disease is limited in extent with preserved lung function and no significant functional impairment; transplant assessment is reserved for advanced, progressive disease unresponsive to treatment.', 3),
('de000000-0000-0000-0000-000000000013', 'D', 'Start nintedanib now as first-line therapy before considering immunosuppression', false, 'Ruled out because in limited extent, stable SSc-ILD without evidence of progression, treatment is not yet indicated at all; when treatment is required for progressive SSc-ILD, immunosuppression (e.g. mycophenolate, or tocilizumab in appropriate patients) is typically considered, with nintedanib an option particularly for progressive fibrosing phenotypes, but none of this applies to this stable, asymptomatic, limited-extent case.', 4),
('de000000-0000-0000-0000-000000000013', 'E', 'Perform surgical lung biopsy to confirm the histological subtype before any further management decisions', false, 'Ruled out because HRCT combined with clinical context is sufficient for diagnosis and risk-stratification in CTD-ILD in most cases; surgical biopsy carries significant risk and is not required when the diagnosis is already clear and disease extent is limited.', 5),
('de000000-0000-0000-0000-000000000014', 'A', 'Community-acquired bacterial pneumonia', false, 'Ruled out because there is no fever, purulent sputum, or growth on blood/sputum cultures, and the clinical/radiological pattern (bilateral ground-glass on a background of known fibrosis, over days) is more consistent with an acute exacerbation than typical bacterial pneumonia.', 1),
('de000000-0000-0000-0000-000000000014', 'B', 'Acute pulmonary embolism', false, 'Ruled out because CT pulmonary angiogram has specifically excluded pulmonary embolism in this vignette.', 2),
('de000000-0000-0000-0000-000000000014', 'C', 'Acute exacerbation of idiopathic pulmonary fibrosis', true, 'Correct. Acute exacerbation of IPF is defined by significant respiratory worsening over less than 1 month with new bilateral ground-glass opacification and/or consolidation superimposed on a background UIP pattern, in the absence of an identifiable alternative cause such as infection, pulmonary embolism, pneumothorax, or cardiac failure — all of which have been reasonably excluded here. It carries a high mortality and is managed with high-dose corticosteroids (despite limited evidence), supportive care, and exclusion/treatment of any identifiable trigger.', 3),
('de000000-0000-0000-0000-000000000014', 'D', 'Decompensated heart failure', false, 'Ruled out because echocardiography shows no evidence of cardiac decompensation, making this an unlikely explanation for the new bilateral changes.', 4),
('de000000-0000-0000-0000-000000000014', 'E', 'Expected, benign progression of underlying disease not requiring any change in management', false, 'Ruled out because this represents an acute, clinically significant deterioration with a specific new radiological pattern superimposed on baseline fibrosis, not simply gradual expected progression; it requires prompt recognition, exclusion of alternative causes, and consideration of specific treatment (corticosteroids) given its high associated mortality.', 5),
('de000000-0000-0000-0000-000000000015', 'A', 'Platinum-doublet chemotherapy alone', false, 'Ruled out because in the presence of a targetable driver mutation such as EGFR exon 19 deletion, targeted therapy (osimertinib) is superior to and preferred over conventional cytotoxic chemotherapy as first-line treatment, reserving chemotherapy for after progression on TKI therapy.', 1),
('de000000-0000-0000-0000-000000000015', 'B', 'Single-agent pembrolizumab immunotherapy', false, 'Ruled out because tumours with actionable driver mutations (EGFR, ALK, ROS1 etc.) generally respond poorly to immune checkpoint inhibitor monotherapy and are typically excluded from upfront immunotherapy approaches; targeted therapy is preferred first-line in EGFR-mutant disease.', 2),
('de000000-0000-0000-0000-000000000015', 'C', 'Combination chemo-immunotherapy (platinum doublet plus pembrolizumab)', false, 'Ruled out because standard chemo-immunotherapy combinations are for driver-mutation-negative NSCLC; in EGFR-mutant tumours, targeted EGFR-TKI therapy takes priority as it offers superior efficacy and tolerability compared to chemo-immunotherapy in this molecular subgroup.', 3),
('de000000-0000-0000-0000-000000000015', 'D', 'Osimertinib (third-generation EGFR tyrosine kinase inhibitor)', true, 'Correct. Osimertinib is the preferred first-line treatment for advanced NSCLC harbouring a sensitising EGFR mutation (exon 19 deletion or L858R), shown in the FLAURA trial to significantly improve progression-free and overall survival compared with earlier-generation EGFR-TKIs, with good CNS penetration and a favourable toxicity profile, avoiding the need for cytotoxic chemotherapy as initial therapy.', 4),
('de000000-0000-0000-0000-000000000015', 'E', 'Best supportive care only, given metastatic disease at presentation', false, 'Ruled out because he has good performance status and a highly actionable, treatable molecular target; effective systemic targeted therapy with meaningful survival benefit is available and should be offered rather than supportive care alone.', 5),
('de000000-0000-0000-0000-000000000016', 'A', 'Surveillance imaging alone with no further active treatment', false, 'Ruled out because consolidation durvalumab has a proven survival benefit in this exact clinical scenario (unresectable stage III NSCLC responding to chemoradiotherapy) and should be offered rather than observation alone in a fit patient without contraindications.', 1),
('de000000-0000-0000-0000-000000000016', 'B', 'Surgical resection of residual disease', false, 'Ruled out because her disease was unresectable at diagnosis (stage III, treated with definitive chemoradiotherapy rather than a surgical approach); response to chemoradiotherapy does not typically convert unresectable disease to a surgical candidate in this context, and consolidation immunotherapy is the evidence-based next step.', 2),
('de000000-0000-0000-0000-000000000016', 'C', 'Further platinum-doublet chemotherapy for an additional 4 cycles', false, 'Ruled out because additional chemotherapy beyond concurrent chemoradiotherapy is not standard; consolidation durvalumab, not further chemotherapy, is the evidence-based approach after response to chemoradiotherapy in stage III disease.', 3),
('de000000-0000-0000-0000-000000000016', 'D', 'Consolidation durvalumab (anti-PD-L1 immunotherapy) for up to 12 months', true, 'Correct. Following the PACIFIC trial, consolidation durvalumab after concurrent chemoradiotherapy in unresectable stage III NSCLC without disease progression significantly improves progression-free and overall survival, and is standard of care in patients with adequate performance status and no contraindications to immunotherapy, regardless of PD-L1 status in many protocols (though PD-L1 ≥1% is required in some regulatory settings).', 4),
('de000000-0000-0000-0000-000000000016', 'E', 'Palliative radiotherapy to symptomatic sites only, deferring systemic therapy', false, 'Ruled out because she has good performance status, a good response to curative-intent chemoradiotherapy, and no mention of progressive/symptomatic disease requiring palliation; consolidation durvalumab aims for improved long-term disease control, not palliation.', 5),
('de000000-0000-0000-0000-000000000017', 'A', 'Continue pembrolizumab unchanged and treat symptomatically with loperamide only', false, 'Ruled out because loperamide alone is inappropriate and potentially harmful in immune-related colitis (risking toxic megacolon by masking severity), and continuing an immune checkpoint inhibitor through significant colitis risks worsening bowel inflammation and complications; treatment should be withheld and corticosteroids started.', 1),
('de000000-0000-0000-0000-000000000017', 'B', 'Withhold pembrolizumab and start high-dose oral or IV corticosteroids for immune-related colitis', true, 'Correct. This presentation (diarrhoea, abdominal cramping, colonic wall thickening on imaging, negative infective work-up) in a patient on checkpoint inhibitor therapy is consistent with immune-related colitis, a common and potentially serious immune-related adverse event. Grade 2-3 colitis is managed with treatment interruption and corticosteroids (oral for milder, IV for more severe grades), with escalation to infliximab or vedolizumab if there is inadequate response within 48-72 hours.', 2),
('de000000-0000-0000-0000-000000000017', 'C', 'Arrange urgent colectomy as first-line management', false, 'Ruled out because surgery is reserved for colitis complicated by perforation, toxic megacolon, or failure of medical therapy including biologics; first-line management of immune-related colitis is corticosteroids, with escalation to infliximab/vedolizumab before surgery is considered.', 3),
('de000000-0000-0000-0000-000000000017', 'D', 'Start empirical broad-spectrum antibiotics for presumed infective colitis', false, 'Ruled out because infective causes (including C. difficile) have already been excluded, and the clinical context (recent checkpoint inhibitor exposure, colonic thickening) points to an immune-mediated aetiology rather than infection, for which antibiotics would not be effective.', 4),
('de000000-0000-0000-0000-000000000017', 'E', 'Switch pembrolizumab to a different checkpoint inhibitor without treating the colitis', false, 'Ruled out because switching to another checkpoint inhibitor does not address the active immune-related adverse event and risks similar or worse toxicity; the priority is to treat the colitis (corticosteroids) and reassess future immunotherapy suitability afterwards.', 5),
('de000000-0000-0000-0000-000000000018', 'A', 'Routine surveillance CT in 12 months with no further intervention now', false, 'Ruled out because a 22 mm solid nodule with moderate-high FDG avidity in a heavy smoker has a substantial probability of malignancy according to validated risk models (e.g. Brock/Herder models); surveillance alone without tissue diagnosis or intervention would be inappropriate and could delay treatment of an early, potentially curable cancer.', 1),
('de000000-0000-0000-0000-000000000018', 'B', 'Reassure the patient that the nodule is benign given the absence of nodal disease on PET-CT', false, 'Ruled out because absence of nodal/distant disease on PET-CT indicates early stage if malignant, not that the primary nodule itself is benign; a moderately FDG-avid solid nodule of this size in a smoker still requires tissue diagnosis or resection to determine malignancy.', 2),
('de000000-0000-0000-0000-000000000018', 'C', 'Tissue diagnosis via CT-guided or bronchoscopic (e.g. navigation) biopsy, or proceed directly to surgical resection if multidisciplinary team consensus supports high pre-test probability of malignancy', true, 'Correct. A solid, FDG-avid nodule of this size with a significant smoking history carries a high probability of malignancy. Depending on multidisciplinary team discussion, either a tissue diagnosis is obtained (to confirm malignancy and guide staging/histology-directed treatment) or, in selected high pre-test probability cases with good surgical fitness, the patient may proceed directly to diagnostic-therapeutic surgical resection; either pathway requires MDT input rather than either simple surveillance or an assumption of benignity.', 3),
('de000000-0000-0000-0000-000000000018', 'D', 'Start empirical treatment for presumed infective granuloma with antibiotics', false, 'Ruled out because there is no clinical or radiological picture suggestive of active infection; empirical antibiotic treatment would not be appropriate management of a nodule with these high-risk features without evidence of infection.', 4),
('de000000-0000-0000-0000-000000000018', 'E', 'Repeat PET-CT in 3 months to reassess FDG avidity before any tissue sampling', false, 'Ruled out because with a nodule of this size and avidity in a high-risk patient, proceeding to tissue diagnosis (or resection per MDT) without delay is appropriate; repeating PET-CT would simply delay diagnosis and treatment of a potentially early, curable malignancy.', 5),
('de000000-0000-0000-0000-000000000019', 'A', 'Observation alone with routine surveillance brain MRI, without PCI', false, 'Ruled out because PCI has a demonstrated overall survival benefit in limited-stage SCLC responders (not solely a reduction in brain metastasis incidence), so surveillance imaging alone without PCI is not the standard evidence-based approach in a good responder with good performance status.', 1),
('de000000-0000-0000-0000-000000000019', 'B', 'Further platinum-etoposide chemotherapy cycles beyond the standard course', false, 'Ruled out because SCLC chemotherapy is typically given for a defined number of cycles (commonly 4-6); continuing chemotherapy indefinitely is not standard and PCI, not additional chemotherapy cycles, is the recognised next step after a good response in limited-stage disease.', 2),
('de000000-0000-0000-0000-000000000019', 'C', 'Maintenance immunotherapy with a checkpoint inhibitor in limited-stage disease', false, 'Ruled out because maintenance immune checkpoint inhibitor therapy after chemoradiotherapy has an established role in extensive-stage SCLC (and is being studied in limited-stage), but the well-established next step specifically for limited-stage SCLC responders remains PCI; this is not the standard next step described here.', 3),
('de000000-0000-0000-0000-000000000019', 'D', 'Repeat concurrent chemoradiotherapy course to consolidate response', false, 'Ruled out because a second full course of concurrent chemoradiotherapy is not standard practice after a good response to a single course; PCI is the established consolidation approach in this setting.', 4),
('de000000-0000-0000-0000-000000000019', 'E', 'Prophylactic cranial irradiation (PCI)', true, 'Correct. In limited-stage small cell lung cancer with a good response to chemoradiotherapy, prophylactic cranial irradiation reduces the incidence of symptomatic brain metastases and improves overall survival, given the high propensity of SCLC to metastasise to the brain even in the absence of detectable disease at restaging. It is offered to responders with good performance status.', 5),
('de000000-0000-0000-0000-000000000020', 'A', 'Immune checkpoint inhibitor-related pneumonitis; withhold pembrolizumab and start corticosteroids', true, 'Correct. New bilateral ground-glass change with breathlessness and cough in a patient on immunotherapy, without evidence of infection, is characteristic of checkpoint inhibitor-related pneumonitis. Management depends on grade: for grade ≥2, immunotherapy should be withheld and corticosteroids started promptly, with bronchoscopy/BAL considered to help exclude infection and escalation to additional immunosuppression (e.g. infliximab, mycophenolate) if steroid-refractory.', 1),
('de000000-0000-0000-0000-000000000020', 'B', 'Disease progression with lymphangitic spread of the primary tumour; continue current regimen unchanged', false, 'Ruled out because the pattern (bilateral, patchy ground-glass, distinct from known tumour sites, temporally associated with recent immunotherapy) is more consistent with drug-induced pneumonitis than lymphangitic carcinomatosis; continuing unchanged treatment risks worsening a potentially serious immune-related toxicity.', 2),
('de000000-0000-0000-0000-000000000020', 'C', 'Pemetrexed-induced pulmonary toxicity requiring only chemotherapy dose reduction', false, 'Ruled out because although pemetrexed can rarely cause pneumonitis, the combination with a checkpoint inhibitor and this classic radiological/clinical pattern makes immune-related pneumonitis the leading diagnosis requiring treatment interruption and corticosteroids, not simply chemotherapy dose reduction.', 3),
('de000000-0000-0000-0000-000000000020', 'D', 'Atypical pneumonia requiring empirical macrolide antibiotics as sole treatment', false, 'Ruled out because infective work-up (including viral PCR) is negative and inflammatory markers are normal, making infection less likely as the primary explanation; empirical antibiotics alone would not address the likely immune-mediated process.', 4),
('de000000-0000-0000-0000-000000000020', 'E', 'Congestive cardiac failure secondary to anthracycline-related cardiotoxicity', false, 'Ruled out because her regimen (carboplatin, pemetrexed, pembrolizumab) does not include an anthracycline, and there is no supporting cardiac history or examination findings given; this diagnosis does not fit the clinical picture.', 5),
('de000000-0000-0000-0000-000000000021', 'A', 'Switch immediately to a different next-generation ALK inhibitor across the board', false, 'Ruled out because widespread systemic switch is not necessary when disease is otherwise well controlled and progression is isolated to a single new small CNS lesion; local therapy combined with continuation of the current effective agent is preferred, reserving a systemic switch for more widespread or symptomatic progression.', 1),
('de000000-0000-0000-0000-000000000021', 'B', 'Stop alectinib and commence platinum-doublet chemotherapy', false, 'Ruled out because alectinib remains effective at all other disease sites; switching to chemotherapy would abandon a still-effective targeted therapy for an issue that can be addressed locally.', 2),
('de000000-0000-0000-0000-000000000021', 'C', 'Whole brain radiotherapy as first-line management of this isolated lesion', false, 'Ruled out because a single small isolated lesion is preferentially managed with stereotactic radiosurgery to minimise neurocognitive toxicity, reserving whole brain radiotherapy for multiple or diffuse CNS disease not amenable to focal treatment.', 3),
('de000000-0000-0000-0000-000000000021', 'D', 'Observation alone with repeat imaging in 3 months, given he remains asymptomatic', false, 'Ruled out because a new CNS lesion, even if asymptomatic, represents disease progression that should be addressed proactively with local therapy to prevent neurological complications, rather than simply observed.', 4),
('de000000-0000-0000-0000-000000000021', 'E', 'Continue alectinib and treat the isolated new CNS lesion with stereotactic radiosurgery (local oligoprogression management)', true, 'Correct. Isolated CNS oligoprogression on an otherwise effective and well-tolerated targeted therapy is best managed by continuing the systemic agent (which remains effective at all other disease sites) while treating the new isolated lesion locally with stereotactic radiosurgery, rather than abandoning an effective systemic therapy. This maximises disease control while addressing the site of progression directly.', 5),
('de000000-0000-0000-0000-000000000022', 'A', 'Repeated therapeutic aspiration only, as needed, without any definitive pleurodesis or catheter option', false, 'Ruled out because repeated simple aspiration is associated with high recurrence rates and multiple hospital attendances; definitive management with pleurodesis or an indwelling catheter is preferred to reduce the burden of repeated procedures, particularly as he specifically wants to avoid this.', 1),
('de000000-0000-0000-0000-000000000022', 'B', 'Immediate surgical pleurectomy/decortication as the only effective option', false, 'Ruled out because pleurectomy/decortication is a more invasive surgical approach generally reserved for selected cases (e.g. trapped lung, or as part of multimodality mesothelioma treatment in fit patients), not the default first option when simpler outpatient-friendly strategies (pleurodesis, IPC) are available and effective.', 2),
('de000000-0000-0000-0000-000000000022', 'C', 'Long-term diuretic therapy to reduce pleural fluid accumulation', false, 'Ruled out because malignant pleural effusions result from pleural malignant infiltration and increased vascular permeability, not fluid overload, so diuretics have no meaningful role in controlling malignant effusion recurrence.', 3),
('de000000-0000-0000-0000-000000000022', 'D', 'Discuss and offer either talc pleurodesis or an indwelling pleural catheter, based on patient preference and expected prognosis/lung re-expansion', true, 'Correct. In patients with malignant pleural effusion and full lung re-expansion (no trapped lung), both talc pleurodesis and indwelling pleural catheter (IPC) are effective options for preventing fluid recurrence, with trials (e.g. TAPPS) showing broadly comparable control of breathlessness; the choice should be guided by shared decision-making incorporating patient preference, desire to avoid hospital admission (favouring IPC, which allows outpatient drainage), expected survival, and local expertise.', 4),
('de000000-0000-0000-0000-000000000022', 'E', 'Chest drain insertion with prolonged inpatient admission until spontaneous pleurodesis occurs, without talc instillation', false, 'Ruled out because prolonged inpatient drainage without active pleurodesis (e.g. talc) is inefficient, prolongs hospital stay unnecessarily, and is not the preferred strategy when talc pleurodesis or an outpatient indwelling catheter can achieve similar or better control with less hospitalisation.', 5),
('de000000-0000-0000-0000-000000000023', 'A', 'Therapeutic aspiration alone, with no chest drain required', false, 'Ruled out because a complicated parapneumonic effusion/empyema (pH <7.2, organisms present, purulent fluid) requires tube drainage, not simple aspiration alone, as aspiration alone has a high failure rate in this setting and delays source control.', 1),
('de000000-0000-0000-0000-000000000023', 'B', 'Oral antibiotics alone with outpatient follow-up', false, 'Ruled out because this represents a complicated parapneumonic effusion with biochemical and microbiological evidence of infection requiring drainage; oral antibiotics without drainage and without inpatient monitoring would be inadequate and unsafe given the severity of findings.', 2),
('de000000-0000-0000-0000-000000000023', 'C', 'Insertion of an intercostal chest drain with appropriate antibiotics, and consideration of intrapleural fibrinolytic/DNase therapy if drainage is inadequate', true, 'Correct. Pleural fluid pH <7.2, low glucose, and grossly purulent/organism-positive fluid indicate a complicated parapneumonic effusion/empyema requiring prompt chest tube drainage alongside IV antibiotics; if drainage is inadequate or loculation is present (often confirmed on ultrasound/CT), intrapleural fibrinolytic and DNase therapy (e.g. tPA/DNase per the MIST2 protocol) improves drainage and reduces need for surgery.', 3),
('de000000-0000-0000-0000-000000000023', 'D', 'Immediate surgical decortication as first-line management before attempting drainage', false, 'Ruled out because chest tube drainage with antibiotics (plus intrapleural fibrinolytics/DNase if needed) is first-line management for empyema; surgery (e.g. VATS decortication) is reserved for cases that fail to respond to drainage and fibrinolytic therapy, not as an immediate first step.', 4),
('de000000-0000-0000-0000-000000000023', 'E', 'Repeat chest X-ray in 48 hours with no active intervention in the interim', false, 'Ruled out because the pleural fluid findings (pH 7.05, low glucose, organisms seen, high LDH) indicate an established complicated parapneumonic effusion/empyema requiring prompt drainage; delaying intervention risks clinical deterioration and increased likelihood of needing surgery.', 5),
('de000000-0000-0000-0000-000000000024', 'A', 'Conservative management with observation, given he is minimally symptomatic, with outpatient follow-up and safety-netting advice', true, 'Correct. Current BTS guidance emphasises that in primary spontaneous pneumothorax, conservative management (observation) is now the preferred initial approach even for moderate-to-large pneumothoraces in minimally symptomatic, stable patients, given comparable resolution rates to intervention with fewer complications; intervention (needle aspiration or chest drain) is reserved for patients who are significantly breathless or clinically unstable regardless of pneumothorax size.', 1),
('de000000-0000-0000-0000-000000000024', 'B', 'Immediate large-bore chest drain insertion, as this is a large pneumothorax by BTS size criteria', false, 'Ruled out because current BTS guidance has moved away from using size alone to mandate intervention; a stable, minimally symptomatic patient can be managed conservatively regardless of size, with intervention reserved for significant symptoms or instability.', 2),
('de000000-0000-0000-0000-000000000024', 'C', 'Needle aspiration as the mandatory first-line intervention in all primary pneumothoraces of this size', false, 'Ruled out because needle aspiration is no longer considered the default first step for pneumothoraces of this size in an asymptomatic/minimally symptomatic stable patient under the updated conservative-first approach; it remains an option when intervention is needed but is not mandatory here.', 3),
('de000000-0000-0000-0000-000000000024', 'D', 'Immediate video-assisted thoracoscopic surgery (VATS) for definitive management', false, 'Ruled out because surgical intervention is reserved for recurrent pneumothorax, persistent air leak, or failure of conservative/drainage management, not as a first-line approach to a first presentation of primary spontaneous pneumothorax.', 4),
('de000000-0000-0000-0000-000000000024', 'E', 'Discharge with no follow-up required, as primary spontaneous pneumothorax always resolves without recurrence', false, 'Ruled out because although conservative management is appropriate, patients require follow-up (clinical review and repeat imaging) with clear safety-netting advice regarding worsening symptoms, and recurrence is not uncommon, particularly in smokers or those with underlying bullous disease.', 5),
('de000000-0000-0000-0000-000000000025', 'A', 'Repeat pleural fluid cytology a third time before considering biopsy', false, 'Ruled out because cytology has a limited sensitivity for mesothelioma and repeating it a third time is unlikely to be diagnostic; tissue biopsy (image-guided or thoracoscopic) is required to obtain adequate material for histological diagnosis, including immunohistochemistry.', 1),
('de000000-0000-0000-0000-000000000025', 'B', 'Local anaesthetic thoracoscopy (medical thoracoscopy) or CT/ultrasound-guided pleural biopsy targeting the nodular thickening', true, 'Correct. When pleural fluid cytology is inconclusive and mesothelioma is suspected (asbestos exposure, nodular circumferential pleural thickening), image-guided (CT or ultrasound) biopsy targeting areas of nodular thickening, or local anaesthetic thoracoscopy (which allows direct visualisation and biopsy under vision with high diagnostic yield and can also achieve pleurodesis in the same procedure), is the appropriate next step to obtain adequate tissue for histological and immunohistochemical diagnosis.', 2),
('de000000-0000-0000-0000-000000000025', 'C', 'Empirical talc pleurodesis without further tissue diagnosis', false, 'Ruled out because a definitive tissue diagnosis is essential before proceeding to definitive management, both to confirm mesothelioma (versus other malignant or benign causes) and to guide subtype-specific treatment planning and any medico-legal/compensation processes relevant to occupational asbestos exposure.', 3),
('de000000-0000-0000-0000-000000000025', 'D', 'PET-CT alone to confirm the diagnosis without tissue sampling', false, 'Ruled out because PET-CT can support staging and identify FDG-avid areas to target for biopsy, but it cannot provide a definitive histological diagnosis; tissue sampling remains necessary.', 4),
('de000000-0000-0000-0000-000000000025', 'E', 'Bronchoscopy with transbronchial biopsy as the investigation of choice', false, 'Ruled out because mesothelioma is a pleural-based disease; transbronchial biopsy via bronchoscopy samples the airways/parenchyma and has very low yield for pleural-based pathology compared with image-guided or thoracoscopic pleural biopsy.', 5),
('de000000-0000-0000-0000-000000000026', 'A', 'Malignant pleural effusion secondary to an HIV-associated lymphoma; start chemotherapy empirically', false, 'Ruled out because pleural fluid cytology shows no malignant cells, and the markedly elevated ADA with lymphocytic exudate in this clinical context is far more consistent with tuberculous pleuritis than lymphoma; empirical chemotherapy without histological confirmation of malignancy would be inappropriate.', 1),
('de000000-0000-0000-0000-000000000026', 'B', 'Bacterial parapneumonic effusion; treat with broad-spectrum antibiotics alone', false, 'Ruled out because the clinical picture (subacute fever, night sweats, lymphocyte-predominant exudate, high ADA) does not fit a typical bacterial parapneumonic process, which usually causes a neutrophil-predominant exudate; the findings instead point strongly toward tuberculous pleuritis.', 2),
('de000000-0000-0000-0000-000000000026', 'C', 'Await pleural fluid mycobacterial culture results (several weeks) before starting any treatment', false, 'Ruled out because in a patient with advanced immunosuppression and a high pre-test probability picture, empirical treatment should not be delayed for culture confirmation, which can take several weeks; treatment should start on the balance of clinical, biochemical, and risk-factor evidence, while culture/biopsy confirmation is pursued in parallel.', 3),
('de000000-0000-0000-0000-000000000026', 'D', 'Tuberculous pleural effusion; start empirical anti-tuberculous therapy while awaiting further confirmatory tests (pleural biopsy/culture)', true, 'Correct. A lymphocyte-predominant exudative effusion with a markedly elevated pleural fluid ADA (typically >40 U/L) in a patient at high risk (immunocompromised, systemic symptoms) is highly suggestive of tuberculous pleuritis, even with negative AFB smears, since smear sensitivity is low in pleural TB. Given his significant immunocompromise and high pre-test probability, empirical anti-tuberculous therapy should be started promptly while pursuing further confirmation (pleural biopsy for histology/culture, which has higher sensitivity than fluid alone), rather than delaying treatment pending culture results that take weeks.', 4),
('de000000-0000-0000-0000-000000000026', 'E', 'Reassure the patient this is a transudative effusion related to hypoalbuminaemia and can be observed', false, 'Ruled out because the fluid is described as exudative with elevated ADA and clear systemic infective symptoms, which is inconsistent with a simple transudate from hypoalbuminaemia; active investigation and treatment for the likely underlying infective cause is required.', 5),
('de000000-0000-0000-0000-000000000027', 'A', 'Spontaneous bacterial empyema requiring immediate broad-spectrum antibiotics', false, 'Ruled out because there is no evidence of infection on pleural fluid analysis in this vignette; while spontaneous bacterial pleural infection (spontaneous bacterial empyema) can complicate hepatic hydrothorax, it is not supported here and antibiotics are not indicated without infective markers.', 1),
('de000000-0000-0000-0000-000000000027', 'B', 'Malignant pleural effusion from an occult hepatocellular carcinoma', false, 'Ruled out because the fluid is a transudate matching serum biochemistry without cytological evidence of malignancy; a malignant effusion would typically be exudative, and this would require further specific evidence before being invoked, especially when a well-recognised, more common explanation (hepatic hydrothorax) fits the whole clinical picture.', 2),
('de000000-0000-0000-0000-000000000027', 'C', 'Hepatic hydrothorax due to direct passage of ascitic fluid through diaphragmatic defects', true, 'Correct. Hepatic hydrothorax occurs when ascitic fluid passes through small diaphragmatic defects (often right-sided, related to the higher frequency of right hemidiaphragm defects and negative intrathoracic pressure during inspiration acting as a pump) into the pleural space; it can occur even with minimal clinically apparent ascites and produces a transudative effusion reflecting serum/ascitic fluid biochemistry.', 3),
('de000000-0000-0000-0000-000000000027', 'D', 'Parapneumonic effusion secondary to an undiagnosed pneumonia', false, 'Ruled out because there is no mention of infective symptoms, fever, or an exudative/purulent fluid profile; a transudative effusion in the context of known cirrhosis is much better explained by hepatic hydrothorax.', 4),
('de000000-0000-0000-0000-000000000027', 'E', 'Nephrotic syndrome causing bilateral transudative effusions', false, 'Ruled out because the effusion is unilateral (right-sided) and there is no mention of renal disease or nephrotic-range proteinuria; the clinical context of cirrhosis with a unilateral right-sided transudate is classic for hepatic hydrothorax rather than a renal cause.', 5),
('de000000-0000-0000-0000-000000000028', 'A', 'Transudate, most likely due to left ventricular dysfunction/early cardiac failure', true, $x$Correct. None of Light's criteria are met: pleural/serum protein ratio is 28/68 = 0.41 (<0.5), pleural/serum LDH ratio is 140/210 = 0.67 (<0.6 is required to be transudate by that specific criterion, but overall combined with the other two negative criteria and pleural LDH being less than two-thirds the upper limit of normal serum LDH, this is transudative), and pleural LDH is well below two-thirds the upper limit of normal serum LDH. Together with reduced LV ejection fraction, this supports a transudative effusion secondary to cardiac dysfunction, which does not require pleural fluid sampling to further investigate once the transudative nature is established and a clear cause (heart failure) is identified.$x$, 1),
('de000000-0000-0000-0000-000000000028', 'B', 'Exudate, requiring further investigation with CT and pleural biopsy', false, $x$Ruled out because none of Light's criteria are met (protein ratio <0.5, LDH ratio <0.6, pleural LDH less than two-thirds upper limit of normal serum LDH), so this is a transudate; transudative effusions with an identifiable systemic cause (here, cardiac dysfunction) generally do not require further invasive pleural investigation.$x$, 2),
('de000000-0000-0000-0000-000000000028', 'C', 'Exudate, most likely representing early pleural malignancy requiring urgent biopsy', false, $x$Ruled out because the fluid meets transudate criteria by Light's criteria, and a clear alternative explanation (reduced LV function) is present; invasive biopsy is not the appropriate next step for a straightforward transudative effusion with an identified systemic cause.$x$, 3),
('de000000-0000-0000-0000-000000000028', 'D', 'Transudate, most likely due to nephrotic syndrome given the low pleural protein', false, 'Ruled out because there is no supporting clinical or biochemical evidence of nephrotic syndrome (renal disease, hypoalbuminaemia, proteinuria) provided, whereas reduced LV ejection fraction on echocardiogram directly supports a cardiac cause for this transudate.', 4),
('de000000-0000-0000-0000-000000000028', 'E', 'Cannot be classified without pleural fluid cholesterol level', false, $x$Ruled out because Light's criteria (based on pleural/serum protein and LDH ratios, and absolute pleural LDH relative to serum upper limit of normal) are sufficient to classify this effusion as a transudate; cholesterol-based criteria are an alternative/adjunct method but are not required when Light's criteria clearly classify the fluid.$x$, 5),
('de000000-0000-0000-0000-000000000029', 'A', 'Therapeutic dose low molecular weight heparin alone, with no thrombolysis', false, 'Ruled out because anticoagulation alone is insufficient in high-risk PE with haemodynamic compromise; thrombolysis is required to address the acute RV strain and hypotension, since anticoagulation alone does not actively dissolve existing clot burden quickly enough in this unstable scenario.', 1),
('de000000-0000-0000-0000-000000000029', 'B', 'Insertion of an inferior vena cava filter as the primary intervention', false, 'Ruled out because IVC filters prevent further embolisation from lower limb DVT but do not treat the existing large clot burden or haemodynamic compromise; they are not primary therapy for high-risk PE and are reserved for specific situations (e.g. absolute contraindication to anticoagulation with ongoing VTE risk).', 2),
('de000000-0000-0000-0000-000000000029', 'C', 'Discharge home with outpatient direct oral anticoagulant therapy given bilateral but segmental (not large proximal) emboli', false, 'Ruled out because his haemodynamic instability (hypotension, tachycardia, hypoperfusion, RV dysfunction) defines high-risk PE regardless of the anatomical distribution being segmental; this requires urgent inpatient management with thrombolysis, not outpatient anticoagulation.', 3),
('de000000-0000-0000-0000-000000000029', 'D', 'Urgent surgical embolectomy as first-line therapy ahead of thrombolysis', false, 'Ruled out because systemic thrombolysis is first-line for high-risk PE without contraindications; surgical (or catheter-directed) embolectomy is reserved for those with contraindications to thrombolysis or in whom thrombolysis has failed, given the greater invasiveness and resource requirements of surgery.', 4),
('de000000-0000-0000-0000-000000000029', 'E', 'Systemic thrombolysis (e.g. alteplase), unless there is a strong contraindication', true, 'Correct. This presentation — hypotension, tachycardia, hypoperfusion (cool peripheries, raised lactate), and echocardiographic evidence of RV strain in confirmed PE — meets criteria for high-risk (massive) PE with haemodynamic compromise. Systemic thrombolysis is indicated to rapidly reduce clot burden and RV strain, reducing mortality, provided there is no major contraindication (e.g. recent haemorrhagic stroke, active bleeding), in which case catheter-directed therapy or surgical embolectomy would be considered instead.', 5),
('de000000-0000-0000-0000-000000000030', 'A', 'Stop anticoagulation now, as 6 months of treatment is always sufficient regardless of provocation status', false, 'Ruled out because provoked and unprovoked VTE are managed differently: unprovoked events carry a high recurrence risk after stopping treatment, favouring consideration of extended anticoagulation rather than a fixed universal 6-month stop rule.', 1),
('de000000-0000-0000-0000-000000000030', 'B', 'Discuss extended (indefinite) anticoagulation, using a validated bleeding risk assessment and shared decision-making, given her unprovoked PE', true, 'Correct. Unprovoked VTE carries a substantial risk of recurrence after stopping anticoagulation (approximately 10% at 1 year and 30-40% at 5 years), which generally exceeds the risk of major bleeding on extended anticoagulation in patients without significant bleeding risk factors. Current guidance recommends considering extended (indefinite) anticoagulation for unprovoked VTE after an individualised discussion incorporating bleeding risk, patient preference, and possibly a reduced-dose DOAC regimen for extended-phase treatment.', 2),
('de000000-0000-0000-0000-000000000030', 'C', 'Switch to aspirin monotherapy for long-term secondary prevention instead of continued anticoagulation', false, 'Ruled out because aspirin is substantially less effective than anticoagulation for secondary VTE prevention; it may be considered only in patients who decline or are unsuitable for continued anticoagulation, not as an equivalent first-choice alternative.', 3),
('de000000-0000-0000-0000-000000000030', 'D', 'Arrange thrombophilia testing repeat annually to guide the anticoagulation duration decision', false, 'Ruled out because the decision to extend anticoagulation for unprovoked VTE is based primarily on recurrence risk and bleeding risk assessment rather than repeated thrombophilia testing, and an initial unremarkable screen does not need annual repetition to guide this decision.', 4),
('de000000-0000-0000-0000-000000000030', 'E', 'Continue full-dose anticoagulation for exactly 12 months and then stop automatically', false, 'Ruled out because there is no fixed 12-month rule for unprovoked VTE; the decision on duration (including possible indefinite extension) should be individualised based on recurrence versus bleeding risk, not an automatic stop at an arbitrary time point.', 5),
('de000000-0000-0000-0000-000000000031', 'A', 'CT pulmonary angiogram alone is sufficient, with no need for right heart catheterisation', false, 'Ruled out because while CTPA is useful for anatomical assessment, formal haemodynamic confirmation of pulmonary hypertension via right heart catheterisation is required before a CTEPH diagnosis is established and before definitive treatment planning (including surgical candidacy assessment) can proceed.', 1),
('de000000-0000-0000-0000-000000000031', 'B', 'Repeat 6-minute walk test alone to assess functional capacity before further investigation', false, 'Ruled out because functional testing does not establish or confirm the diagnosis of pulmonary hypertension; invasive haemodynamic assessment via right heart catheterisation is required for diagnostic confirmation.', 2),
('de000000-0000-0000-0000-000000000031', 'C', 'Right heart catheterisation with pulmonary angiography to confirm chronic thromboembolic pulmonary hypertension and assess operability', true, 'Correct. The clinical picture (progressive breathlessness after prior PE, echocardiographic evidence of pulmonary hypertension, and multiple mismatched perfusion defects on V/Q scan) is strongly suggestive of chronic thromboembolic pulmonary hypertension (CTEPH). Right heart catheterisation is required to confirm the haemodynamic diagnosis of pulmonary hypertension (mean PAP ≥20 mmHg with appropriate other criteria) and pulmonary angiography (CT or conventional) helps define the distribution of disease and assess suitability for pulmonary endarterectomy, the potentially curative treatment.', 3),
('de000000-0000-0000-0000-000000000031', 'D', 'Empirical initiation of long-term therapeutic anticoagulation without further diagnostic work-up, given her PE history', false, 'Ruled out because although lifelong anticoagulation is indicated once CTEPH is confirmed, this alone does not address the diagnostic confirmation needed, nor the crucial assessment of operability for pulmonary endarterectomy, which is potentially curative and should not be bypassed by simply resuming anticoagulation without further work-up.', 4),
('de000000-0000-0000-0000-000000000031', 'E', 'High-resolution CT chest to assess for interstitial lung disease as the primary alternative diagnosis', false, 'Ruled out because the clinical and V/Q scan findings point specifically toward a chronic thromboembolic process rather than interstitial lung disease, and HRCT would not confirm or exclude pulmonary hypertension or CTEPH in this context.', 5),
('de000000-0000-0000-0000-000000000032', 'A', 'Low molecular weight heparin is mandatory in all cancer-associated thrombosis, with DOACs contraindicated', false, 'Ruled out because while LMWH remains a well-established and preferred option in specific situations (e.g. luminal GI cancers with high bleeding risk, significant drug interactions, or patient inability to take oral medication), DOACs are not contraindicated across the board and are now a guideline-supported option for many patients with cancer-associated thrombosis, particularly given his preference to avoid injections.', 1),
('de000000-0000-0000-0000-000000000032', 'B', 'A direct oral anticoagulant (e.g. apixaban or rivaroxaban), taking into account bleeding risk and potential drug interactions with his chemotherapy', true, 'Correct. Current evidence and guidelines support DOACs (particularly apixaban, and rivaroxaban/edoxaban) as effective alternatives to low molecular weight heparin for cancer-associated thrombosis in patients without gastrointestinal or genitourinary malignancy at high bleeding risk, offering the practical advantage of oral dosing over daily injections, provided there are no significant drug-drug interactions with his chemotherapy regimen and no contraindications.', 2),
('de000000-0000-0000-0000-000000000032', 'C', 'Warfarin with INR target 2-3 as first-line therapy', false, 'Ruled out because warfarin is generally less effective than LMWH or DOACs for cancer-associated thrombosis, with less predictable dosing given interactions with chemotherapy, nutritional status, and hepatic function; it is not first-line in this context.', 3),
('de000000-0000-0000-0000-000000000032', 'D', 'Aspirin monotherapy given his high bleeding risk profile from malignancy', false, 'Ruled out because aspirin is substantially less effective than anticoagulation for treatment of confirmed venous thromboembolism and is not an appropriate treatment for an acute PE, regardless of malignancy status.', 4),
('de000000-0000-0000-0000-000000000032', 'E', 'Inferior vena cava filter insertion as definitive treatment, without anticoagulation', false, 'Ruled out because IVC filters do not treat the existing thrombus and are not a substitute for anticoagulation; they are reserved for patients with an absolute contraindication to anticoagulation, which does not apply here.', 5),
('de000000-0000-0000-0000-000000000033', 'A', 'Standard D-dimer testing followed by no further imaging if positive, given the high sensitivity of D-dimer in pregnancy', false, 'Ruled out because D-dimer is physiologically elevated throughout pregnancy and has poor specificity in this context, so it is not used to guide the decision for further imaging in suspected PE during pregnancy; imaging is required regardless of D-dimer result when clinical suspicion is present.', 1),
('de000000-0000-0000-0000-000000000033', 'B', 'Pulmonary angiography (invasive conventional angiography) as first-line investigation', false, 'Ruled out because invasive pulmonary angiography carries higher risk and radiation exposure compared with CTPA or V/Q scanning, and is not first-line for suspected PE in pregnancy or otherwise; it is reserved for specific circumstances such as pre-endarterectomy assessment.', 2),
('de000000-0000-0000-0000-000000000033', 'C', 'MRI pulmonary angiography as the investigation of choice in pregnancy', false, 'Ruled out because MRI pulmonary angiography is not a standard, validated first-line investigation for acute PE in pregnancy due to limited sensitivity for pulmonary emboli compared with CTPA/V/Q scanning; it is not part of routine practice for this indication.', 3),
('de000000-0000-0000-0000-000000000033', 'D', 'Bilateral lower limb compression ultrasound first if there are symptoms/signs of DVT; otherwise proceed directly to V/Q scan or CTPA per local protocol', true, 'Correct. In pregnancy, if there are symptoms or signs suggesting concurrent DVT, bilateral leg compression ultrasound is performed first, as a positive result confirms VTE and avoids further fetal radiation exposure. If there is no DVT suspected or ultrasound is negative/inconclusive, definitive pulmonary imaging (V/Q scan or CTPA, chosen per local protocol/resources, both being considered acceptable with low fetal radiation risk and similar diagnostic accuracy) is required, as a normal chest X-ray does not exclude PE.', 4),
('de000000-0000-0000-0000-000000000033', 'E', 'No imaging is required; treat empirically with therapeutic anticoagulation based on clinical suspicion alone', false, 'Ruled out because definitive imaging confirmation is required before committing a pregnant patient to a prolonged course of therapeutic anticoagulation, given the implications for the remainder of pregnancy and delivery planning; empirical treatment without imaging is not standard practice when suspicion is high but not certain.', 5),
('de000000-0000-0000-0000-000000000034', 'A', 'Outpatient management with a direct oral anticoagulant, provided appropriate follow-up and safety-netting are arranged', true, 'Correct. Validated risk stratification tools (such as the PESI or simplified PESI score) identify low-risk PE patients who can be safely managed as outpatients with a DOAC, avoiding unnecessary hospital admission, provided there are no other reasons for admission (e.g. poor social circumstances, significant comorbidity, high bleeding risk) and appropriate follow-up/safety-netting is arranged.', 1),
('de000000-0000-0000-0000-000000000034', 'B', 'Mandatory inpatient admission for all confirmed pulmonary emboli regardless of risk stratification', false, 'Ruled out because low-risk PE, identified using validated scoring systems, can be safely managed as an outpatient; blanket admission for all PE regardless of severity is not evidence-based practice and leads to unnecessary hospital utilisation.', 2),
('de000000-0000-0000-0000-000000000034', 'C', 'Admission to a critical care unit for close monitoring given the diagnosis of PE', false, 'Ruled out because critical care admission is reserved for high-risk (massive) PE with haemodynamic compromise or significant comorbidity/complication risk, not for confirmed low-risk PE meeting outpatient criteria.', 3),
('de000000-0000-0000-0000-000000000034', 'D', 'Inpatient admission for at least 5 days of low molecular weight heparin before considering discharge on oral anticoagulation', false, 'Ruled out because with a DOAC-based approach and confirmed low-risk features, there is no requirement for an initial inpatient heparin lead-in period or minimum admission duration; several DOACs can be started directly (with an initial higher-dose loading phase for some agents) in the outpatient setting.', 4),
('de000000-0000-0000-0000-000000000034', 'E', $x$Discharge with no anticoagulation, given the diagnosis is 'low-risk'$x$, false, 'Ruled out because low-risk still refers to risk of early mortality/complications, not absence of need for treatment; confirmed PE still requires anticoagulation to treat existing thrombus and prevent extension/recurrence/embolisation, simply delivered in the outpatient rather than inpatient setting.', 5),
('de000000-0000-0000-0000-000000000035', 'A', 'Continue rivaroxaban unchanged through surgery given the recency of her DVT', false, 'Ruled out because continuing full anticoagulation through an urgent surgical procedure carries unacceptable bleeding risk; a brief, appropriately timed interruption is required even in recently diagnosed VTE, balanced against thrombotic risk which is generally still manageable with a short interruption.', 1),
('de000000-0000-0000-0000-000000000035', 'B', 'Switch to bridging therapy with therapeutic low molecular weight heparin before and after surgery', false, 'Ruled out because routine heparin bridging is not required when interrupting DOAC therapy for surgery, as DOACs have predictable offset of effect; bridging increases bleeding risk without added thrombotic protection in this context, unlike bridging strategies historically used with warfarin.', 2),
('de000000-0000-0000-0000-000000000035', 'C', 'Delay surgery for a minimum of 3 months until VTE treatment is complete', false, 'Ruled out because acute cholecystitis failing conservative management requires urgent surgical management; delaying necessary urgent surgery for 3 months would risk significant complications (perforation, sepsis) from the underlying surgical condition, and is not required — anticoagulation can be safely and briefly interrupted instead.', 3),
('de000000-0000-0000-0000-000000000035', 'D', 'Insert a retrievable inferior vena cava filter to allow safe cessation of anticoagulation before surgery', false, 'Ruled out because IVC filter insertion for a routine, brief perioperative anticoagulation interruption in a patient without a contraindication to anticoagulation is not standard practice; it is reserved for specific high-risk scenarios where anticoagulation must be stopped for a prolonged period or is contraindicated altogether.', 4),
('de000000-0000-0000-0000-000000000035', 'E', 'Stop rivaroxaban with an appropriate short interruption based on renal function and bleeding risk of the procedure, without routine heparin bridging', true, $x$Correct. DOACs have a relatively short half-life allowing simple, timed interruption before surgery based on the drug's pharmacokinetics, renal function, and the bleeding risk of the planned procedure, without the need for heparin bridging (unlike warfarin), since therapeutic anticoagulant effect resolves predictably within 1-2 days in patients with normal renal function; bridging with heparin actually increases bleeding risk without proven benefit for most DOAC-treated patients requiring surgery.$x$, 5),
('de000000-0000-0000-0000-000000000036', 'A', 'CURB-65 score of 2; manage as moderate-severity pneumonia suitable for a general ward with oral antibiotics', false, 'Ruled out because he meets all five CURB-65 criteria (confusion, urea >7, RR ≥30, BP <90/60, age ≥65), giving a score of 5, not 2; this represents severe, high-mortality-risk pneumonia requiring urgent escalation, not oral antibiotics on a general ward.', 1),
('de000000-0000-0000-0000-000000000036', 'B', 'CURB-65 score of 1; suitable for outpatient (community) management with oral antibiotics', false, 'Ruled out because his multiple severe physiological derangements (hypotension, confusion, tachypnoea, renal impairment marker) place him at the maximum CURB-65 score, representing severe pneumonia with a high mortality risk — entirely unsuitable for outpatient management.', 2),
('de000000-0000-0000-0000-000000000036', 'C', 'CURB-65 score of 5; manage as severe pneumonia with urgent senior/critical care input, combination IV antibiotics, and consideration of ICU admission', true, 'Correct. He scores 5 out of 5 on CURB-65 (Confusion, Urea >7 mmol/L, Respiratory rate ≥30/min, Blood pressure <90 systolic or ≤60 diastolic, Age ≥65), indicating very high mortality risk. This mandates urgent senior clinical review, prompt broad-spectrum IV combination antibiotic therapy per local severe CAP protocol, aggressive fluid resuscitation for his hypotension, and early critical care/ICU involvement given the high risk of deterioration and need for organ support.', 3),
('de000000-0000-0000-0000-000000000036', 'D', 'CURB-65 is not validated in patients over 70 and should not be used; manage based on clinical gestalt alone', false, 'Ruled out because CURB-65 explicitly incorporates age ≥65 as one of its criteria and is a validated tool across the adult population including elderly patients; it remains a core part of severity assessment and should be used alongside, not instead of, clinical judgement.', 4),
('de000000-0000-0000-0000-000000000036', 'E', 'Discharge with a course of oral amoxicillin and safety-netting advice', false, 'Ruled out because a CURB-65 score of 5 identifies very high mortality risk pneumonia requiring urgent inpatient management with IV antibiotics and likely critical care support, not outpatient discharge.', 5),
('de000000-0000-0000-0000-000000000037', 'A', 'Continue co-amoxiclav unchanged, as it has broad-spectrum activity covering most respiratory pathogens', false, 'Ruled out because co-amoxiclav does not have reliable activity against Pseudomonas aeruginosa, which has now been identified as the causative organism with defined sensitivities; continuing an ineffective agent risks ongoing clinical deterioration.', 1),
('de000000-0000-0000-0000-000000000037', 'B', 'Add oral doxycycline to broaden atypical pathogen cover', false, 'Ruled out because the identified organism is Pseudomonas aeruginosa, not an atypical pathogen; doxycycline would not provide appropriate additional cover for the confirmed causative organism, and antibiotic choice should be directed by the culture and sensitivity results.', 2),
('de000000-0000-0000-0000-000000000037', 'C', 'Switch to IV benzylpenicillin as targeted narrow-spectrum therapy', false, 'Ruled out because benzylpenicillin has no useful activity against Pseudomonas aeruginosa; targeted therapy must use an agent to which the organism is shown to be sensitive.', 3),
('de000000-0000-0000-0000-000000000037', 'D', 'No change in antibiotics; continue current therapy and add antifungal cover instead', false, 'Ruled out because the confirmed pathogen is a bacterium (Pseudomonas aeruginosa) with a defined antibiotic sensitivity profile; antifungal therapy is not indicated based on the information given, and antibiotics should be changed to a susceptibility-guided antipseudomonal agent.', 4),
('de000000-0000-0000-0000-000000000037', 'E', 'Switch to an antipseudomonal agent such as IV piperacillin-tazobactam, guided by sensitivities', true, 'Correct. His risk factors (severe COPD, recurrent hospitalisations, multiple prior antibiotic courses) predispose to Pseudomonas aeruginosa infection, now confirmed on culture with sensitivities available; treatment should be switched to a susceptibility-guided antipseudomonal agent (e.g. piperacillin-tazobactam or ciprofloxacin), as standard CAP antibiotics like co-amoxiclav do not reliably cover Pseudomonas.', 5),
('de000000-0000-0000-0000-000000000038', 'A', 'Sputum Gram stain and culture on standard media alone', false, 'Ruled out because Legionella is a fastidious organism that does not grow on standard sputum culture media and requires specialised buffered charcoal yeast extract (BCYE) agar; the urinary antigen test is faster and more practical as an initial diagnostic step, though sputum culture on appropriate media remains useful for confirmation and strain typing.', 1),
('de000000-0000-0000-0000-000000000038', 'B', 'Legionella urinary antigen test', true, 'Correct. The clinical picture (travel history with potential water system exposure, systemic symptoms including confusion and diarrhoea, hyponatraemia, deranged LFTs, patchy bilateral consolidation) is highly suggestive of Legionella pneumonia. The urinary antigen test is rapid, widely available, and detects Legionella pneumophila serogroup 1 (responsible for the majority of clinical cases), making it the most appropriate initial test to support the diagnosis and guide targeted antibiotic therapy.', 2),
('de000000-0000-0000-0000-000000000038', 'C', 'Pneumococcal urinary antigen test', false, 'Ruled out because while pneumococcal urinary antigen testing may be part of a broader pneumonia work-up, it would not identify Legionella, which is the pathogen most strongly suggested by this specific clinical picture and exposure history.', 3),
('de000000-0000-0000-0000-000000000038', 'D', 'Bronchoalveolar lavage with routine bacterial culture only, without atypical pathogen testing', false, 'Ruled out because bronchoscopy is invasive and not first-line when a rapid non-invasive test (urinary antigen) can support the likely diagnosis; if performed, samples would specifically need to be sent for Legionella-directed testing (culture on BCYE agar, PCR), not routine bacterial culture alone.', 4),
('de000000-0000-0000-0000-000000000038', 'E', 'Serum cold agglutinins', false, 'Ruled out because cold agglutinins are associated with Mycoplasma pneumoniae infection, not Legionella; the exposure history (hotel water/air conditioning system) and multisystem features point specifically toward Legionella.', 5),
('de000000-0000-0000-0000-000000000039', 'A', 'IV liposomal amphotericin B as first-line therapy', false, 'Ruled out because amphotericin B is not first-line treatment for PCP; high-dose co-trimoxazole is the treatment of choice, with amphotericin having no established primary role in this specific infection.', 1),
('de000000-0000-0000-0000-000000000039', 'B', 'Await bronchoscopy and BAL microscopy for definitive PCP confirmation before starting treatment', false, 'Ruled out because in a patient with a high pre-test probability and clinical severity, empirical treatment should be started without waiting for invasive confirmation, since Pneumocystis organisms can still be detected on BAL even after treatment has commenced for a reasonable window, and delaying treatment risks clinical deterioration.', 2),
('de000000-0000-0000-0000-000000000039', 'C', 'Co-trimoxazole alone, withholding corticosteroids regardless of hypoxaemia severity', false, 'Ruled out because adjunctive corticosteroids have a proven mortality benefit in moderate-to-severe PCP (significant hypoxaemia) by attenuating the inflammatory response as organisms are killed, and should be given alongside co-trimoxazole in this hypoxaemic patient, not withheld.', 3),
('de000000-0000-0000-0000-000000000039', 'D', 'High-dose co-trimoxazole (trimethoprim-sulfamethoxazole), with adjunctive corticosteroids given significant hypoxaemia', true, 'Correct. This presentation (advanced HIV with low CD4 count, subacute breathlessness, exertional desaturation, bilateral perihilar interstitial infiltrates, raised beta-D-glucan) is classic for Pneumocystis jirovecii pneumonia (PCP). First-line treatment is high-dose co-trimoxazole; given significant hypoxaemia (exercise desaturation to 88%, and particularly if resting pO2 <9.3 kPa or SpO2 <92% on air), adjunctive corticosteroids are indicated to reduce the inflammatory response to organism death and reduce risk of respiratory failure, and treatment should not be delayed pending definitive microbiological confirmation (e.g. BAL) in a clinically compatible high-probability case.', 4),
('de000000-0000-0000-0000-000000000039', 'E', 'Isoniazid, rifampicin, pyrazinamide, and ethambutol for presumed pulmonary tuberculosis', false, 'Ruled out because although TB must always be considered in HIV, the specific clinical pattern here (exertional desaturation, bilateral perihilar interstitial infiltrates, raised beta-D-glucan, subacute course) is much more characteristic of PCP; empirical anti-TB therapy would not address the most likely diagnosis, though co-infection should still be actively excluded.', 5),
('de000000-0000-0000-0000-000000000040', 'A', 'Isolate appropriately and refer urgently to a specialist multidrug-resistant TB service for individualised regimen selection based on full drug susceptibility testing', true, 'Correct. Rifampicin resistance detected on rapid molecular testing (GeneXpert) is a marker for likely multidrug-resistant TB (resistance to at least rifampicin and isoniazid) and mandates urgent referral to a specialist MDR-TB service. Management requires further full first- and second-line drug susceptibility testing to guide an individualised regimen, appropriate respiratory isolation (given ongoing infectivity risk with a resistant organism), and public health notification/contact tracing coordination.', 1),
('de000000-0000-0000-0000-000000000040', 'B', 'Start standard first-line quadruple therapy (rifampicin, isoniazid, pyrazinamide, ethambutol) as for drug-sensitive TB', false, 'Ruled out because standard first-line therapy includes rifampicin, to which resistance has already been confirmed; using this regimen would be ineffective and risks further resistance amplification and ongoing transmission of a resistant strain.', 2),
('de000000-0000-0000-0000-000000000040', 'C', 'Discharge home on directly observed therapy with standard treatment while awaiting further results', false, 'Ruled out because a patient with confirmed rifampicin resistance and positive smear (indicating high infectivity) requires careful management including consideration of isolation and specialist input before an appropriate regimen and community management plan can be safely established; standard first-line therapy would be inappropriate here.', 3),
('de000000-0000-0000-0000-000000000040', 'D', 'Withhold any treatment until full culture-based drug susceptibility results are available in 6-8 weeks', false, 'Ruled out because although full susceptibility testing is important to guide the definitive regimen, urgent specialist referral and initiation of an appropriate presumptive MDR-TB regimen (informed by rapid molecular results and local resistance patterns) should not be delayed for weeks, given ongoing infectivity and disease progression risk.', 4),
('de000000-0000-0000-0000-000000000040', 'E', 'Add a single additional second-line agent to the standard first-line regimen', false, 'Ruled out because adding a single agent to an already-failing (rifampicin-containing) regimen risks further amplifying resistance (the principle of never adding a single drug to a failing regimen); a full individualised multidrug regimen designed by specialists based on susceptibility testing is required.', 5),
('de000000-0000-0000-0000-000000000041', 'A', 'Long-term oral ciprofloxacin as first-line maintenance therapy', false, 'Ruled out because long-term oral fluoroquinolone use for maintenance therapy is generally avoided due to concerns about resistance development, tendinopathy, and other systemic toxicity; nebulised antipseudomonal antibiotics are preferred for long-term suppressive therapy in Pseudomonas-colonised bronchiectasis.', 1),
('de000000-0000-0000-0000-000000000041', 'B', 'Long-term oral azithromycin as first-line therapy given Pseudomonas colonisation', false, 'Ruled out because although long-term macrolides (e.g. azithromycin) reduce exacerbations in bronchiectasis generally, particularly in patients without Pseudomonas, in patients with confirmed chronic Pseudomonas colonisation and frequent exacerbations, targeted long-term antipseudomonal (typically nebulised) therapy is preferred as first-line, with macrolides considered as an alternative or adjunct depending on response and local protocols.', 2),
('de000000-0000-0000-0000-000000000041', 'C', 'Referral for bilateral lung transplantation as the next step', false, 'Ruled out because lung transplantation is reserved for end-stage disease with severe functional impairment refractory to all other treatments; escalating medical therapy (long-term antipseudomonal antibiotics) should be tried first in this patient with recurrent exacerbations but no mention of severe functional decline.', 3),
('de000000-0000-0000-0000-000000000041', 'D', 'Increase frequency of acute antibiotic courses only when exacerbations occur, without any maintenance therapy', false, 'Ruled out because this reactive approach has already been tried (multiple acute exacerbation treatments) without controlling his symptom burden; a proactive long-term suppressive antibiotic strategy is indicated for frequent exacerbators with chronic Pseudomonas colonisation.', 4),
('de000000-0000-0000-0000-000000000041', 'E', 'Long-term nebulised antipseudomonal antibiotic therapy (e.g. nebulised colistin or tobramycin)', true, 'Correct. Chronic Pseudomonas aeruginosa colonisation with frequent exacerbations despite optimised non-pharmacological management (airway clearance, treatment of acute exacerbations) is an indication for long-term nebulised antipseudomonal antibiotics, which reduce bacterial load, exacerbation frequency, and symptom burden in bronchiectasis, per British Thoracic Society guidance.', 5),
('de000000-0000-0000-0000-000000000042', 'A', 'Continue broad-spectrum co-amoxiclav and clarithromycin for the full course regardless of culture results', false, 'Ruled out because continuing unnecessarily broad-spectrum therapy once a susceptible organism is identified and the patient is improving runs counter to antimicrobial stewardship principles and increases risks of resistance and adverse effects without added clinical benefit.', 1),
('de000000-0000-0000-0000-000000000042', 'B', 'Stop all antibiotics immediately given clinical improvement', false, 'Ruled out because a full appropriate course of antibiotic therapy (typically around 5-7 days for uncomplicated CAP, guided by clinical response) is still required even with early improvement; stopping prematurely risks treatment failure or relapse.', 2),
('de000000-0000-0000-0000-000000000042', 'C', 'Add IV vancomycin for additional Gram-positive cover', false, 'Ruled out because the organism is fully sensitive to penicillin; there is no indication for adding vancomycin, which would represent unnecessary broadening of therapy against stewardship principles and without any resistant organism to justify it.', 3),
('de000000-0000-0000-0000-000000000042', 'D', 'De-escalate to a narrow-spectrum agent (e.g. IV then oral amoxicillin) guided by the confirmed sensitivities, once clinically appropriate to switch to oral therapy', true, 'Correct. With a confirmed organism (fully sensitive Streptococcus pneumoniae) and clear clinical improvement, antimicrobial stewardship principles support de-escalating from broad-spectrum empirical therapy (co-amoxiclav plus a macrolide) to a narrow-spectrum, susceptibility-guided agent such as amoxicillin, switching from IV to oral once criteria for switch are met (clinical improvement, ability to take oral medication, haemodynamic stability), reducing unnecessary broad-spectrum exposure and associated risks (resistance, C. difficile).', 4),
('de000000-0000-0000-0000-000000000042', 'E', 'Switch to IV meropenem to ensure broader coverage given bacteraemia', false, 'Ruled out because bacteraemia with a fully penicillin-sensitive organism does not require carbapenem therapy; this would represent significant unnecessary escalation contrary to susceptibility results and stewardship principles.', 5),
('de000000-0000-0000-0000-000000000043', 'A', 'This represents pure chronic hypercapnic COPD; treatment with inhaled bronchodilators alone is indicated', false, 'Ruled out because there is no supporting history or spirometric evidence of COPD given; the clinical picture (obesity, severe OSA, daytime hypercapnia with compensated metabolic alkalosis) is classic for obesity hypoventilation syndrome, which is managed with positive airway pressure therapy, not inhaled bronchodilators.', 1),
('de000000-0000-0000-0000-000000000043', 'B', 'The blood gas findings are incidental and unrelated to his sleep apnoea; no specific action is required beyond standard CPAP for OSA symptoms alone', false, 'Ruled out because awake hypercapnia in a patient with severe OSA and obesity is a significant finding indicating obesity hypoventilation syndrome, which has important prognostic and management implications (need for careful monitoring of ventilatory response to treatment) beyond simply treating OSA symptoms.', 2),
('de000000-0000-0000-0000-000000000043', 'C', 'Obesity hypoventilation syndrome complicating severe OSA; initial treatment with CPAP is appropriate, with escalation to bilevel/NIV if CPAP fails to adequately control nocturnal hypoventilation', true, 'Correct. Awake hypercapnia (pCO2 6.8 kPa) with compensatory raised bicarbonate, in an obese patient with severe OSA and no other cause of chronic respiratory failure, indicates obesity hypoventilation syndrome (OHS) coexisting with OSA. Current evidence supports a trial of CPAP as initial therapy in stable OHS patients with severe coexisting OSA (as here), reserving bilevel/NIV for those who fail to adequately correct nocturnal hypoventilation and hypercapnia on CPAP alone, or who have more severe decompensated presentations.', 3),
('de000000-0000-0000-0000-000000000043', 'D', 'Immediate initiation of long-term home mechanical ventilation via tracheostomy is required as first-line treatment', false, 'Ruled out because non-invasive approaches (starting with CPAP, escalating to bilevel NIV if required) are first-line for OHS with severe OSA; invasive ventilation via tracheostomy is not indicated as an initial approach in a stable patient.', 4),
('de000000-0000-0000-0000-000000000043', 'E', 'Weight loss advice alone, without any positive airway pressure therapy, as this will resolve the hypoventilation over time', false, 'Ruled out because although weight loss is an important long-term management goal in OHS and can improve or resolve the condition, positive airway pressure therapy (CPAP or NIV) is required as first-line treatment to address the current significant hypercapnic respiratory failure and severe OSA, alongside weight loss advice, not instead of it.', 5),
('de000000-0000-0000-0000-000000000044', 'A', 'Trial of non-invasive ventilation, with careful attention to secretion management and cough augmentation strategies given his significant bulbar involvement', true, 'Correct. Nocturnal hypoventilation symptoms with confirmed nocturnal desaturation and daytime hypercapnia in motor neurone disease are an indication for NIV, which improves quality of life and survival in MND with respiratory muscle weakness. However, significant bulbar dysfunction (impaired secretion clearance, weak cough, aspiration risk) makes NIV more challenging and less tolerated, so careful assessment, secretion management (e.g. cough assist devices, suction), and close monitoring are essential alongside its initiation, with a realistic discussion of limitations given his bulbar involvement.', 1),
('de000000-0000-0000-0000-000000000044', 'B', 'Immediate elective tracheostomy ventilation as the only appropriate option given bulbar involvement', false, 'Ruled out because NIV remains the standard first-line approach to ventilatory support in MND, including in patients with some bulbar involvement, with invasive ventilation via tracheostomy being a much bigger decision requiring extensive discussion of goals of care, burden, and patient wishes rather than being the automatic or only option.', 2),
('de000000-0000-0000-0000-000000000044', 'C', 'No ventilatory support is indicated as bulbar dysfunction is an absolute contraindication to NIV', false, 'Ruled out because bulbar dysfunction is not an absolute contraindication to NIV, though it can reduce tolerability and effectiveness (particularly due to aspiration risk and mask-fitting difficulty with excess secretions); a trial with appropriate adjuncts (secretion management) is still appropriate given his significant symptoms and blood gas findings.', 3),
('de000000-0000-0000-0000-000000000044', 'D', 'Start long-term oxygen therapy alone, without ventilatory support', false, 'Ruled out because oxygen therapy alone does not address the underlying hypoventilation and can worsen hypercapnia by blunting hypoxic respiratory drive in a patient with alveolar hypoventilation; NIV is the appropriate treatment to address the ventilatory failure directly.', 4),
('de000000-0000-0000-0000-000000000044', 'E', 'Defer any respiratory intervention until he develops overt respiratory failure requiring emergency admission', false, 'Ruled out because proactive assessment and early initiation of NIV in symptomatic MND patients with evidence of nocturnal hypoventilation improves quality of life and survival; waiting for emergency deterioration misses the opportunity for a more controlled, better-tolerated introduction of support and appropriate advance care planning.', 5),
('de000000-0000-0000-0000-000000000045', 'A', 'He can continue driving as normal while treatment is arranged, provided he feels subjectively alert', false, 'Ruled out because subjective alertness alone is not sufficient; UK law requires DVLA notification and cessation of driving for symptomatic moderate-to-severe OSA until it is adequately treated, particularly critical for HGV licence holders given the higher safety standard and public risk involved.', 1),
('de000000-0000-0000-0000-000000000045', 'B', 'He must inform the DVLA of his diagnosis and should not drive until his symptoms are adequately controlled', true, 'Correct. Moderate-to-severe OSA causing excessive sleepiness is notifiable to the DVLA, and UK regulations require cessation of driving (including HGV licence holders, who are held to stricter standards) until symptoms are satisfactorily controlled, typically with confirmed treatment compliance and resolution of excessive sleepiness; this is a patient safety and legal responsibility that must be clearly communicated and documented.', 2),
('de000000-0000-0000-0000-000000000045', 'C', 'Only private car licence restrictions apply; his HGV licence is unaffected by an OSA diagnosis', false, 'Ruled out because HGV (Group 2) licence holders are subject to stricter DVLA medical standards regarding OSA than private (Group 1) licence holders, given the greater risk associated with commercial vehicle operation; his HGV licence is very much affected and requires closer monitoring/compliance evidence for reinstatement.', 3),
('de000000-0000-0000-0000-000000000045', 'D', 'No notification is required unless he has already had a driving-related accident', false, 'Ruled out because DVLA notification requirements for OSA with excessive sleepiness apply based on the diagnosis and symptom impact, not on whether an accident has already occurred; proactive notification is a legal requirement to prevent harm before it happens.', 4),
('de000000-0000-0000-0000-000000000045', 'E', 'He should stop driving permanently, as OSA is a permanent contraindication to holding an HGV licence', false, 'Ruled out because OSA does not permanently disqualify a patient from holding an HGV licence; driving can typically resume once symptoms are adequately controlled with effective treatment (e.g. CPAP) and compliance is demonstrated, subject to DVLA review, rather than being a permanent ban.', 5),
('de000000-0000-0000-0000-000000000046', 'A', 'Standard fixed-pressure CPAP is the clearly preferred and most effective treatment for this pattern of breathing', false, 'Ruled out because CPAP has more modest and variable efficacy for predominantly central sleep apnoea/Cheyne-Stokes respiration compared with obstructive sleep apnoea, and optimising heart failure treatment is the priority first step, with device therapy considered afterward based on response and specific contraindications (notably avoiding ASV in reduced ejection fraction heart failure).', 1),
('de000000-0000-0000-0000-000000000046', 'B', 'Adaptive servo-ventilation should be started promptly as first-line therapy given its specific design for central sleep apnoea patterns', false, 'Ruled out because although ASV is designed to treat central sleep apnoea/Cheyne-Stokes respiration physiologically, the SERVE-HF trial demonstrated increased cardiovascular mortality when used in patients with symptomatic heart failure and LVEF ≤45%, making it contraindicated in this specific population despite its mechanistic appeal.', 2),
('de000000-0000-0000-0000-000000000046', 'C', 'This represents obstructive sleep apnoea and mandibular advancement device therapy should be arranged', false, 'Ruled out because the described breathing pattern and polysomnography (predominant central events, cyclical crescendo-decrescendo pattern) is characteristic of central sleep apnoea/Cheyne-Stokes respiration, not an obstructive process, so a device targeting upper airway obstruction (mandibular advancement) would not be an appropriate primary intervention.', 3),
('de000000-0000-0000-0000-000000000046', 'D', 'No treatment is required as Cheyne-Stokes respiration in heart failure is a benign, incidental finding', false, 'Ruled out because Cheyne-Stokes respiration/central sleep apnoea is associated with worse heart failure prognosis and requires active attention, starting with optimisation of heart failure therapy; it is not a benign incidental finding to be ignored.', 4),
('de000000-0000-0000-0000-000000000046', 'E', 'Central sleep apnoea with Cheyne-Stokes respiration secondary to heart failure; optimise heart failure therapy first, and note that adaptive servo-ventilation is contraindicated in this population with reduced ejection fraction', true, 'Correct. The cyclical crescendo-decrescendo breathing pattern with central apnoeic pauses in a patient with reduced ejection fraction heart failure is classic Cheyne-Stokes respiration/central sleep apnoea. The first priority is optimising guideline-directed heart failure therapy, which can improve central sleep apnoea. Adaptive servo-ventilation (ASV) is specifically contraindicated in patients with symptomatic heart failure and LVEF ≤45% due to the SERVE-HF trial, which showed increased cardiovascular mortality with ASV in this population, so this should be explicitly avoided even though it might otherwise seem an intuitive ventilatory treatment for central sleep apnoea.', 5),
('de000000-0000-0000-0000-000000000047', 'A', 'Discontinue CPAP immediately and proceed directly to bariatric surgery referral', false, 'Ruled out because mask-related adherence problems are usually addressable with troubleshooting and are not an indication to abandon CPAP outright; surgical options are considered for refractory cases or specific circumstances, not as an immediate response to early mask discomfort.', 1),
('de000000-0000-0000-0000-000000000047', 'B', 'Review and troubleshoot mask fit/type with specialist sleep physiology input, addressing comfort and leak issues before considering alternative therapies', true, 'Correct. Poor CPAP adherence is very commonly related to mask discomfort, poor fit, or leak, and the first step is thorough troubleshooting — trying different mask types/sizes (nasal, nasal pillow, full face), addressing pressure settings, and providing structured support/education — since this often substantially improves comfort and adherence before concluding that CPAP itself has failed or moving to alternative treatments.', 2),
('de000000-0000-0000-0000-000000000047', 'C', 'Increase the CPAP pressure setting to improve efficacy, without addressing the mask issues', false, 'Ruled out because her main problem is mask discomfort/leak affecting tolerance, not inadequate pressure; increasing pressure without addressing the fit/comfort issue is likely to worsen tolerance and adherence further.', 3),
('de000000-0000-0000-0000-000000000047', 'D', 'Switch directly to a mandibular advancement device without further CPAP troubleshooting', false, 'Ruled out because CPAP remains first-line for moderate-severe OSA and mask-related adherence issues should be actively addressed through troubleshooting before considering less effective alternative device therapies typically reserved for mild-moderate OSA or CPAP-intolerant patients after genuine optimisation attempts.', 4),
('de000000-0000-0000-0000-000000000047', 'E', 'Reassure her that 2 hours per night is adequate CPAP usage and no changes are needed', false, 'Ruled out because CPAP benefit is dose-related, and typical adherence targets are usage of at least 4 hours per night on most nights; 2.1 hours average usage is suboptimal and unlikely to provide full symptomatic or cardiovascular benefit, warranting active intervention rather than reassurance.', 5),
('de000000-0000-0000-0000-000000000048', 'A', 'Long-term oxygen therapy alone, without ventilatory support', false, 'Ruled out because oxygen alone does not address the underlying alveolar hypoventilation and can worsen hypercapnia by further blunting respiratory drive; the primary problem here (restrictive chest wall disease causing hypoventilation) requires ventilatory support (NIV), with supplemental oxygen only added if hypoxaemia persists despite adequate ventilation.', 1),
('de000000-0000-0000-0000-000000000048', 'B', 'Corrective spinal surgery as the only definitive and immediately necessary intervention, deferring ventilatory support', false, 'Ruled out because although spinal correction may be considered in some patients (typically earlier in the disease course to prevent progression), in a patient with established chronic hypercapnic respiratory failure, domiciliary NIV is the appropriate immediate management to address current respiratory failure; late-stage surgical correction carries significant risk and would not immediately reverse existing ventilatory failure.', 2),
('de000000-0000-0000-0000-000000000048', 'C', 'Initiate domiciliary non-invasive ventilation, typically starting with overnight bilevel support', true, 'Correct. Severe kyphoscoliosis causing restrictive chest wall disease with evidence of chronic hypercapnic respiratory failure (elevated pCO2 with compensation) and significant nocturnal hypoventilation/desaturation is a well-established indication for domiciliary NIV (typically bilevel), which improves symptoms, gas exchange, and survival in chest wall restrictive disorders by unloading the respiratory muscles and improving alveolar ventilation, particularly overnight when hypoventilation is most pronounced.', 3),
('de000000-0000-0000-0000-000000000048', 'D', 'Reassurance and observation, as chest wall disease does not typically cause clinically significant respiratory failure', false, 'Ruled out because severe kyphoscoliosis is a well-recognised cause of restrictive lung disease progressing to chronic respiratory failure, and she already has objective evidence (blood gas, oximetry, symptoms) of significant hypoventilation requiring active treatment, not observation.', 4),
('de000000-0000-0000-0000-000000000048', 'E', 'Continuous positive airway pressure (CPAP) alone is the treatment of choice for this restrictive ventilatory pattern', false, 'Ruled out because CPAP provides a single fixed pressure without additional inspiratory support to actively augment tidal volume, which is needed to address hypoventilation in restrictive chest wall disease; bilevel NIV (providing separate inspiratory and expiratory pressures) is the appropriate modality to support ventilation in this context.', 5),
('de000000-0000-0000-0000-000000000049', 'A', 'Sodium oxybate (gamma-hydroxybutyrate)', true, 'Correct. Sodium oxybate is uniquely effective for both excessive daytime sleepiness and cataplexy in narcolepsy, working by consolidating nocturnal sleep architecture (increasing slow-wave sleep) and reducing REM-intrusion phenomena including cataplexy; it is an appropriate add-on or alternative when stimulant therapy alone (e.g. modafinil) provides insufficient control, particularly when cataplexy remains a significant problem, as modafinil has little direct effect on cataplexy.', 1),
('de000000-0000-0000-0000-000000000049', 'B', 'Increase modafinil dose beyond currently licensed maximum', false, 'Ruled out because he is already on the maximum tolerated/licensed dose, and modafinil in any case has minimal efficacy against cataplexy specifically (its main effect is on daytime sleepiness), so further dose escalation would not adequately address his cataplexy symptoms even if tolerated.', 2),
('de000000-0000-0000-0000-000000000049', 'C', 'Selective serotonin reuptake inhibitor (SSRI) as monotherapy for both sleepiness and cataplexy', false, 'Ruled out because although antidepressants (SSRIs, SNRIs, tricyclics) can help suppress cataplexy through REM-suppressant effects, they have no significant effect on excessive daytime sleepiness; sodium oxybate offers benefit across both symptom domains, making it a better fit for his combined refractory symptoms.', 3),
('de000000-0000-0000-0000-000000000049', 'D', 'Referral for immediate bariatric surgery to address underlying obesity as the primary treatment', false, 'Ruled out because there is no mention of obesity in this vignette, and even where present, weight management would not be the primary treatment for narcolepsy type 1 with refractory cataplexy and sleepiness; pharmacological therapy targeting the underlying neurochemical deficit is required.', 4),
('de000000-0000-0000-0000-000000000049', 'E', 'Benzodiazepine hypnotic therapy at bedtime as the primary intervention', false, 'Ruled out because benzodiazepines are not an evidence-based primary treatment for narcolepsy or cataplexy and do not address the underlying pathophysiology (orexin/hypocretin deficiency and REM sleep dysregulation) in the way sodium oxybate does.', 5),
('de000000-0000-0000-0000-000000000050', 'A', 'Increase long-term oxygen flow rate to correct the hypercapnia', false, 'Ruled out because increasing oxygen flow in a chronically hypercapnic COPD patient risks worsening hypercapnia further (by blunting hypoxic respiratory drive and via ventilation-perfusion mismatch effects) rather than correcting it; the appropriate intervention for persistent hypercapnia is addition of ventilatory support (NIV), not simply increasing oxygen dose.', 1),
('de000000-0000-0000-0000-000000000050', 'B', 'No further intervention is required as he has already recovered from his acute exacerbation', false, 'Ruled out because persistent significant hypercapnia weeks after exacerbation resolution, despite optimised background therapy, is a specific evidence-based indication for domiciliary NIV; simply noting recovery from the acute event overlooks this important actionable finding with implications for future exacerbation risk and survival.', 2),
('de000000-0000-0000-0000-000000000050', 'C', 'Refer for lung transplantation as the only remaining therapeutic option', false, 'Ruled out because domiciliary NIV is an appropriate and effective intermediate step for persistent post-exacerbation hypercapnia in COPD; transplantation is a much larger step reserved for those who continue to deteriorate despite optimal medical therapy including NIV, not the immediate next step here.', 3),
('de000000-0000-0000-0000-000000000050', 'D', 'Consider domiciliary (home) non-invasive ventilation in addition to long-term oxygen therapy', true, 'Correct. Persistent hypercapnia (pCO2 >7 kPa, or 6-7 kPa with additional risk factors) 2-4 weeks after resolution of an exacerbation requiring acute NIV is an established indication for domiciliary NIV in COPD, based on evidence (e.g. the HOT-HMV trial) that home NIV combined with oxygen therapy reduces readmissions and improves survival compared with oxygen alone in this persistently hypercapnic post-exacerbation population.', 4),
('de000000-0000-0000-0000-000000000050', 'E', 'Start theophylline as the next step to improve ventilatory drive', false, 'Ruled out because theophylline is not an evidence-based treatment for correcting chronic hypercapnic respiratory failure in this context and carries a narrow therapeutic index with significant toxicity risk; domiciliary NIV is the appropriate, evidence-based intervention for persistent post-exacerbation hypercapnia.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('de000000-0000-0000-0000-000000000001', 'Mepolizumab, reslizumab and benralizumab target the IL-5 pathway and are the biologics of choice for severe eosinophilic asthma with blood eosinophils typically ≥300 cells/microlitre and recurrent exacerbations.', 1),
('de000000-0000-0000-0000-000000000001', 'Omalizumab requires evidence of an allergic phenotype with a total IgE level within a defined therapeutic range; a low IgE excludes its use even in severe asthma.', 2),
('de000000-0000-0000-0000-000000000001', 'Biologic selection in severe asthma is guided by phenotyping (blood eosinophils, FeNO, total IgE, allergen sensitisation) rather than a one-size-fits-all approach.', 3),
('de000000-0000-0000-0000-000000000002', 'In frequent COPD exacerbators despite optimised triple inhaled therapy, additional options include roflumilast (chronic bronchitis phenotype), prophylactic azithromycin (with baseline ECG and LFTs), and addressing modifiable factors like inhaler technique and smoking status.', 1),
('de000000-0000-0000-0000-000000000002', 'A raised blood eosinophil count in COPD predicts a good response to inhaled corticosteroids and identifies patients at higher risk of harm from ICS withdrawal.', 2),
('de000000-0000-0000-0000-000000000002', 'Prophylactic macrolide therapy requires exclusion of non-tuberculous mycobacterial infection and baseline cardiac and hepatic assessment due to QT prolongation and hepatotoxicity risk.', 3),
('de000000-0000-0000-0000-000000000003', 'BTS/SIGN acute severe asthma criteria: PEF 33-50%, respiratory rate ≥25/min, heart rate ≥110/min, or inability to complete sentences in one breath — any one feature is sufficient.', 1),
('de000000-0000-0000-0000-000000000003', $x$A 'normal' or rising pCO2 in an acutely breathless asthmatic is a red flag for approaching respiratory failure because hyperventilation should otherwise drive pCO2 down; this should prompt senior/ICU involvement even before pCO2 becomes frankly elevated.$x$, 2),
('de000000-0000-0000-0000-000000000003', 'Life-threatening features (SpO2 <92%, silent chest, cyanosis, exhaustion, arrhythmia, hypotension, confusion) mandate immediate senior review, arterial blood gas, and consideration of HDU/ICU care.', 3),
('de000000-0000-0000-0000-000000000004', 'ABPA is diagnosed on a combination of asthma/cystic fibrosis background, central bronchiectasis, markedly raised total IgE, peripheral eosinophilia, and Aspergillus-specific IgE/skin prick positivity.', 1),
('de000000-0000-0000-0000-000000000004', 'First-line ABPA treatment is oral corticosteroids to suppress the hypersensitivity response; itraconazole is commonly added as a steroid-sparing agent by reducing fungal antigenic load.', 2),
('de000000-0000-0000-0000-000000000004', 'ABPA reflects allergic sensitisation and immune hypersensitivity to Aspergillus, not invasive infection, which is why systemic antifungals like amphotericin have no primary role.', 3),
('de000000-0000-0000-0000-000000000005', 'Endobronchial valve lung volume reduction requires heterogeneous emphysema with a target lobe, intact interlobar fissures, and absence of collateral ventilation (confirmed by CT fissure integrity and/or Chartis assessment) to achieve effective lobar atelectasis.', 1),
('de000000-0000-0000-0000-000000000005', 'Home NIV in COPD is indicated for chronic hypercapnic respiratory failure, not breathlessness from hyperinflation alone.', 2),
('de000000-0000-0000-0000-000000000005', 'Bronchoscopic lung volume reduction is generally preferred over surgical lung volume reduction in suitable candidates due to a more favourable risk profile, reserving surgery for those unsuitable for valves.', 3),
('de000000-0000-0000-0000-000000000006', 'Inducible laryngeal obstruction (vocal cord dysfunction) is an important asthma mimic/co-morbidity causing episodic breathlessness, stridor, and poor response to asthma therapy; it is confirmed by laryngoscopy during symptomatic episodes, ideally with provocation.', 1),
('de000000-0000-0000-0000-000000000006', 'Flattening of both inspiratory and expiratory limbs of the flow-volume loop suggests a variable extrathoracic (upper airway) obstruction, as opposed to the expiratory-only flattening typical of intrathoracic asthma.', 2),
('de000000-0000-0000-0000-000000000006', 'Failure to respond to escalating asthma treatment should prompt reconsideration of the diagnosis and screening for asthma mimics such as vocal cord dysfunction, dysfunctional breathing, or bronchiectasis.', 3),
('de000000-0000-0000-0000-000000000007', 'Benralizumab targets the IL-5 receptor alpha subunit and causes near-complete eosinophil depletion via antibody-dependent cellular cytotoxicity, distinguishing its mechanism from mepolizumab and reslizumab, which bind IL-5 itself and only reduce (not eliminate) eosinophils.', 1),
('de000000-0000-0000-0000-000000000007', 'A very low or undetectable eosinophil count in a patient established on benralizumab is an expected pharmacodynamic marker of drug effect, not a laboratory abnormality requiring further work-up.', 2),
('de000000-0000-0000-0000-000000000007', 'Understanding biologic mechanisms of action helps distinguish expected on-treatment laboratory changes from genuine new pathology.', 3),
('de000000-0000-0000-0000-000000000008', 'Pirfenidone and nintedanib are the two licensed antifibrotic agents proven to slow FVC decline in IPF, and should be considered at diagnosis in patients with mild-to-moderate disease rather than delayed.', 1),
('de000000-0000-0000-0000-000000000008', 'The PANTHER-IPF trial demonstrated harm (increased mortality) from prednisolone/azathioprine/N-acetylcysteine triple therapy in IPF, fundamentally changing management away from immunosuppression.', 2),
('de000000-0000-0000-0000-000000000008', 'IPF is pathophysiologically a fibroproliferative disease rather than a primarily inflammatory one, explaining why antifibrotics (not immunosuppressants) are the evidence-based treatment.', 3),
('de000000-0000-0000-0000-000000000009', 'Progressive pulmonary fibrosis (PPF) is defined by radiological progression and/or physiological decline (e.g. relative FVC decline ≥10%, or smaller declines with worsening symptoms/imaging) in a fibrosing ILD despite standard management, regardless of underlying cause.', 1),
('de000000-0000-0000-0000-000000000009', 'The INBUILD trial established nintedanib as effective in slowing FVC decline across progressive fibrosing ILDs beyond IPF, including connective tissue disease-associated ILD, hypersensitivity pneumonitis, and other fibrotic ILDs.', 2),
('de000000-0000-0000-0000-000000000009', 'In CTD-ILD, antifibrotic therapy is typically added alongside, not instead of, ongoing immunosuppression, since both inflammatory and fibrotic components may be contributing to progression.', 3),
('de000000-0000-0000-0000-000000000010', 'Hypersensitivity pneumonitis (extrinsic allergic alveolitis) results from an immune-mediated response to inhaled organic antigens (e.g. avian proteins, mouldy hay); complete antigen avoidance is the cornerstone of management and improves outcomes even before pharmacological treatment.', 1),
('de000000-0000-0000-0000-000000000010', 'HRCT features supporting non-fibrotic HP include ground-glass opacification, mosaic attenuation with air trapping on expiratory imaging, and centrilobular nodules, distinguishing it from a UIP/fibrotic pattern.', 2),
('de000000-0000-0000-0000-000000000010', 'Positive serum precipitins support antigen exposure/sensitisation but must be interpreted alongside clinical and radiological findings, as they can also be found in asymptomatic exposed individuals; ongoing unmodified exposure is a key driver of progression to fibrosis.', 3),
('de000000-0000-0000-0000-000000000011', 'Diarrhoea is the most frequent adverse effect of nintedanib; standard management is anti-diarrhoeal therapy (loperamide) with hydration and dietary advice, escalating to dose reduction or temporary treatment interruption if it persists or is severe, before considering discontinuation.', 1),
('de000000-0000-0000-0000-000000000011', 'Both antifibrotics have characteristic tolerability profiles: nintedanib is associated with gastrointestinal effects (diarrhoea, nausea) and liver enzyme derangement, while pirfenidone is associated with photosensitivity, rash, and gastrointestinal upset.', 2),
('de000000-0000-0000-0000-000000000011', 'Regular monitoring (including liver function tests) and proactive management of known adverse effects allow most patients to remain on antifibrotic therapy long-term, maximising the chance of sustained benefit.', 3),
('de000000-0000-0000-0000-000000000012', 'Scadding stage II sarcoidosis (bilateral hilar lymphadenopathy plus parenchymal infiltrates) with minimal symptoms and preserved lung function is typically managed with observation, given high rates of spontaneous remission.', 1),
('de000000-0000-0000-0000-000000000012', 'Corticosteroid treatment in sarcoidosis is reserved for significant or progressive symptoms, declining lung function, or involvement of critical organs (cardiac, neurological, ocular, renal), not for radiographic findings alone.', 2),
('de000000-0000-0000-0000-000000000012', 'Histological confirmation of non-caseating granulomas with exclusion of infective causes (TB, fungal) is required before a sarcoidosis diagnosis is accepted, but re-biopsy is unnecessary once this has been achieved.', 3),
('de000000-0000-0000-0000-000000000013', 'In systemic sclerosis-associated ILD, disease extent on HRCT (limited vs extensive, often using a 10-20% threshold) and baseline/trajectory of lung function are key determinants of prognosis and the decision to treat.', 1),
('de000000-0000-0000-0000-000000000013', 'Limited-extent, stable, asymptomatic SSc-ILD can reasonably be managed with surveillance rather than immediate immunosuppression or antifibrotic therapy, reserving treatment escalation for evidence of progression.', 2),
('de000000-0000-0000-0000-000000000013', 'Treatment options for progressive SSc-ILD include immunosuppression (e.g. mycophenolate mofetil, cyclophosphamide, tocilizumab) and, for a progressive fibrosing phenotype, the addition of nintedanib.', 3),
('de000000-0000-0000-0000-000000000014', 'Acute exacerbation of IPF is defined by acute (<1 month) clinically significant respiratory worsening with new bilateral ground-glass opacification/consolidation superimposed on a background UIP pattern, after excluding alternative causes (infection, PE, pneumothorax, heart failure, fluid overload).', 1),
('de000000-0000-0000-0000-000000000014', 'AE-IPF carries a very high in-hospital mortality; management is largely supportive, alongside high-dose corticosteroids despite limited robust evidence, and exclusion/treatment of any identifiable precipitant.', 2),
('de000000-0000-0000-0000-000000000014', 'A thorough work-up (cultures, CTPA, echocardiography) to exclude alternative and potentially treatable causes of deterioration is essential before labelling a presentation as an acute exacerbation.', 3),
('de000000-0000-0000-0000-000000000015', 'Osimertinib is preferred first-line therapy for EGFR-mutant (exon 19 deletion or L858R) advanced NSCLC based on superior progression-free and overall survival versus earlier-generation TKIs, with the added benefit of good CNS penetration.', 1),
('de000000-0000-0000-0000-000000000015', 'Comprehensive molecular testing (EGFR, ALK, ROS1, BRAF, MET, RET, KRAS G12C, PD-L1) should be performed before starting first-line systemic therapy in advanced non-squamous NSCLC to guide targeted treatment selection.', 2),
('de000000-0000-0000-0000-000000000015', 'Immune checkpoint inhibitors are generally less effective as monotherapy in driver-mutation-positive NSCLC, so targeted therapy takes priority over immunotherapy in these molecular subgroups.', 3),
('de000000-0000-0000-0000-000000000016', 'The PACIFIC trial established consolidation durvalumab after concurrent chemoradiotherapy as standard of care for unresectable stage III NSCLC without progression, substantially improving progression-free and overall survival.', 1),
('de000000-0000-0000-0000-000000000016', 'Consolidation immunotherapy should be started promptly after completion of chemoradiotherapy (typically within 6 weeks) in appropriate candidates with good performance status and no significant pneumonitis or other contraindications.', 2),
('de000000-0000-0000-0000-000000000016', 'Stage III NSCLC management depends critically on resectability: resectable disease may proceed to surgery (with or without neoadjuvant/adjuvant therapy), while unresectable disease is treated with definitive concurrent chemoradiotherapy followed by consolidation immunotherapy.', 3),
('de000000-0000-0000-0000-000000000017', 'Immune-related colitis from checkpoint inhibitor therapy presents with diarrhoea and abdominal pain; infective causes (including C. difficile) must be excluded, but a compatible picture with negative infective work-up should prompt treatment as immune-mediated.', 1),
('de000000-0000-0000-0000-000000000017', 'Management of immune-related colitis is graded: mild cases may be managed with treatment interruption and monitoring, moderate-severe cases require corticosteroids, and steroid-refractory cases are escalated to infliximab or vedolizumab.', 2),
('de000000-0000-0000-0000-000000000017', 'Immune-related adverse events can affect any organ system (colitis, pneumonitis, hepatitis, endocrinopathies, dermatitis) and require a low threshold for suspicion in any patient on checkpoint inhibitor therapy presenting with new symptoms.', 3),
('de000000-0000-0000-0000-000000000018', 'Solitary pulmonary nodule risk assessment integrates size, growth, FDG avidity on PET-CT, and patient risk factors (smoking history, age, family history) using validated prediction models to estimate malignancy probability and guide the diagnostic pathway.', 1),
('de000000-0000-0000-0000-000000000018', 'High pre-test probability nodules in fit patients may proceed directly to diagnostic-therapeutic surgical resection after MDT discussion, rather than requiring a preceding biopsy in every case.', 2),
('de000000-0000-0000-0000-000000000018', 'Timely diagnosis and staging of early-stage lung cancer is critical, as this represents the population with the highest chance of cure through surgical resection or radical radiotherapy.', 3),
('de000000-0000-0000-0000-000000000019', 'Prophylactic cranial irradiation improves overall survival in limited-stage SCLC patients who respond well to initial chemoradiotherapy, reflecting the high rate of occult/subsequent brain metastasis in this disease even without imaging evidence at restaging.', 1),
('de000000-0000-0000-0000-000000000019', 'Limited-stage SCLC (disease confined to a tolerable radiotherapy field, roughly corresponding to stage I-III) is treated with concurrent chemoradiotherapy with curative intent, in contrast to extensive-stage disease which is treated with systemic chemo-immunotherapy.', 2),
('de000000-0000-0000-0000-000000000019', 'SCLC has a markedly higher and earlier propensity for brain metastasis compared with NSCLC, which is central to the rationale for cranial irradiation strategies in both limited- and extensive-stage disease.', 3),
('de000000-0000-0000-0000-000000000020', 'Checkpoint inhibitor pneumonitis presents with new dyspnoea, cough, and bilateral ground-glass or other infiltrates on imaging, typically after exclusion of infection; grade ≥2 disease requires treatment interruption and corticosteroids.', 1),
('de000000-0000-0000-0000-000000000020', 'Distinguishing immune-related pneumonitis from infection, disease progression (lymphangitic spread), and other drug toxicities (e.g. pemetrexed) requires a combination of clinical timeline, radiological pattern, and microbiological work-up, sometimes including bronchoscopy with BAL.', 2),
('de000000-0000-0000-0000-000000000020', 'Steroid-refractory immune-related pneumonitis is escalated to additional immunosuppression such as infliximab or mycophenolate mofetil, mirroring management principles used across other immune-related adverse events.', 3),
('de000000-0000-0000-0000-000000000021', 'Oligoprogression on an effective targeted therapy (a limited number of new/progressing sites with the rest of the disease controlled) is often managed with local therapy (surgery/radiosurgery) to the progressing site(s) while continuing the systemic agent, rather than switching systemic treatment.', 1),
('de000000-0000-0000-0000-000000000021', 'Stereotactic radiosurgery is preferred over whole brain radiotherapy for a limited number of small brain metastases, due to comparable local control with significantly reduced neurocognitive toxicity.', 2),
('de000000-0000-0000-0000-000000000021', 'Newer generation ALK inhibitors (e.g. alectinib, brigatinib, lorlatinib) have good CNS penetration, but isolated CNS oligoprogression can still occur and is managed with local therapy rather than automatic systemic switch.', 3),
('de000000-0000-0000-0000-000000000022', 'In malignant pleural effusion with full lung re-expansion, both talc pleurodesis and indwelling pleural catheters are evidence-based options for symptom control, and the choice should be individualised based on patient preference, prognosis, and desire to minimise hospital admissions.', 1),
('de000000-0000-0000-0000-000000000022', 'Indwelling pleural catheters allow intermittent outpatient drainage and can also achieve spontaneous pleurodesis over time, making them attractive for patients wishing to avoid repeated hospital attendances.', 2),
('de000000-0000-0000-0000-000000000022', 'Trapped lung (failure of full re-expansion after drainage) precludes successful pleurodesis and favours an indwelling pleural catheter as the more appropriate strategy.', 3),
('de000000-0000-0000-0000-000000000023', 'Pleural fluid pH <7.2, glucose <3.3 mmol/L, or the presence of organisms/frank pus defines a complicated parapneumonic effusion or empyema requiring chest tube drainage, not aspiration or antibiotics alone.', 1),
('de000000-0000-0000-0000-000000000023', 'Intrapleural fibrinolytic (e.g. alteplase) combined with DNase therapy improves pleural drainage and reduces the need for surgical intervention in loculated empyema, as shown in the MIST2 trial.', 2),
('de000000-0000-0000-0000-000000000023', 'Surgical options (VATS decortication) are reserved for patients who fail to improve with tube drainage and fibrinolytic therapy, or who have organised, fibrotic pleural disease restricting lung expansion.', 3),
('de000000-0000-0000-0000-000000000024', 'Updated BTS guidance favours conservative management (observation) for primary spontaneous pneumothorax in stable, minimally symptomatic patients regardless of pneumothorax size, reflecting evidence of comparable outcomes to active intervention with fewer complications.', 1),
('de000000-0000-0000-0000-000000000024', 'Indications for active intervention (aspiration or chest drain) are based primarily on significant breathlessness or haemodynamic instability, not pneumothorax size alone.', 2),
('de000000-0000-0000-0000-000000000024', 'All patients managed conservatively require appropriate follow-up, safety-netting advice, and smoking cessation counselling given the association between smoking and pneumothorax recurrence.', 3),
('de000000-0000-0000-0000-000000000025', 'When pleural fluid cytology is inconclusive in suspected mesothelioma, tissue biopsy (image-guided percutaneous or local anaesthetic thoracoscopy) targeting areas of nodular pleural thickening is required for definitive histological diagnosis.', 1),
('de000000-0000-0000-0000-000000000025', 'Local anaesthetic thoracoscopy offers high diagnostic yield through direct visualisation and targeted biopsy, and can allow same-session talc pleurodesis if malignancy is confirmed and lung re-expands fully.', 2),
('de000000-0000-0000-0000-000000000025', 'A history of asbestos exposure with nodular circumferential pleural thickening on imaging is highly suggestive of mesothelioma, but histological confirmation (including immunohistochemistry) is required, both for accurate diagnosis and for occupational/medico-legal purposes.', 3),
('de000000-0000-0000-0000-000000000026', 'A markedly elevated pleural fluid ADA (typically >40 U/L) in a lymphocyte-predominant exudative effusion is highly suggestive of tuberculous pleuritis, particularly in high pre-test probability populations, even when AFB smears are negative due to their low sensitivity.', 1),
('de000000-0000-0000-0000-000000000026', 'In immunocompromised patients with a high clinical probability of tuberculosis, empirical anti-tuberculous therapy should not be delayed pending slow-growing mycobacterial culture results, given the risks of disease progression and transmission.', 2),
('de000000-0000-0000-0000-000000000026', 'Pleural biopsy (for histology showing caseating granulomas, plus culture) has higher diagnostic sensitivity than pleural fluid analysis alone for tuberculous pleuritis and should be pursued for definitive confirmation where feasible.', 3),
('de000000-0000-0000-0000-000000000027', 'Hepatic hydrothorax results from ascitic fluid tracking through small diaphragmatic defects into the pleural space, typically right-sided, and can occur with disproportionately little clinically apparent ascites.', 1),
('de000000-0000-0000-0000-000000000027', 'Management of hepatic hydrothorax focuses on treating the underlying liver disease/portal hypertension (sodium restriction, diuretics, TIPS in refractory cases) rather than repeated thoracentesis alone; chest drains should generally be avoided due to risk of large fluid/protein losses and infection.', 2),
('de000000-0000-0000-0000-000000000027', 'Spontaneous bacterial empyema is a recognised infective complication of hepatic hydrothorax and should always be actively excluded (fluid cell count, culture) when a cirrhotic patient with hydrothorax deteriorates.', 3),
('de000000-0000-0000-0000-000000000028', $x$Light's criteria classify an effusion as exudative if any one of the following is met: pleural/serum protein ratio >0.5, pleural/serum LDH ratio >0.6, or pleural LDH greater than two-thirds the upper limit of normal for serum LDH; failing all three indicates a transudate.$x$, 1),
('de000000-0000-0000-0000-000000000028', 'Transudative effusions (heart failure, cirrhosis, nephrotic syndrome, hypoalbuminaemia) generally reflect a systemic process altering hydrostatic/oncotic pressures and do not require pleural fluid cytology or biopsy once a clear systemic cause is identified and the picture is otherwise unremarkable.', 2),
('de000000-0000-0000-0000-000000000028', 'Cardiac failure is the most common cause of transudative pleural effusion and can be bilateral or, less commonly, unilateral (more often right-sided, though left-sided as here can occur); an echocardiogram showing impaired ventricular function supports this aetiology.', 3),
('de000000-0000-0000-0000-000000000029', 'High-risk (massive) PE is defined by haemodynamic instability (sustained hypotension, cardiogenic shock, or cardiac arrest) in the context of confirmed PE, and is an indication for systemic thrombolysis unless contraindicated.', 1),
('de000000-0000-0000-0000-000000000029', 'Echocardiographic evidence of right ventricular dysfunction supports the diagnosis of significant PE-related haemodynamic compromise and helps risk-stratify patients (alongside biomarkers such as troponin and BNP) even before overt shock develops.', 2),
('de000000-0000-0000-0000-000000000029', 'Contraindications to systemic thrombolysis (e.g. recent stroke, active bleeding, recent major surgery) should prompt consideration of catheter-directed thrombolysis/thrombectomy or surgical embolectomy instead.', 3),
('de000000-0000-0000-0000-000000000030', 'Unprovoked VTE carries a high risk of recurrence after stopping anticoagulation, which generally favours extended (often indefinite) anticoagulation in patients without high bleeding risk, following individualised risk-benefit discussion.', 1),
('de000000-0000-0000-0000-000000000030', 'Reduced-dose DOAC regimens (e.g. apixaban 2.5 mg twice daily, rivaroxaban 10 mg once daily) are validated options for extended-phase VTE prophylaxis after the initial treatment period, balancing continued efficacy with lower bleeding risk.', 2),
('de000000-0000-0000-0000-000000000030', 'Provoked (transient risk factor) VTE is generally treated for a defined shorter duration (typically 3 months) since recurrence risk is much lower once the provoking factor has resolved, in contrast to unprovoked VTE.', 3),
('de000000-0000-0000-0000-000000000031', 'CTEPH should be suspected in patients with persistent or progressive breathlessness following a prior PE, especially with echocardiographic evidence of pulmonary hypertension; V/Q scanning is more sensitive than CTPA for detecting the mismatched perfusion defects typical of chronic thromboembolic disease.', 1),
('de000000-0000-0000-0000-000000000031', 'Right heart catheterisation is required to confirm the haemodynamic diagnosis of pulmonary hypertension and, alongside pulmonary angiography, to assess surgical accessibility of thromboembolic material for pulmonary endarterectomy.', 2),
('de000000-0000-0000-0000-000000000031', 'Pulmonary endarterectomy is potentially curative for operable CTEPH and should be assessed for in all confirmed cases at an expert pulmonary hypertension/CTEPH centre; inoperable or residual disease may be treated with riociguat or balloon pulmonary angioplasty.', 3),
('de000000-0000-0000-0000-000000000032', 'Current guidelines support DOACs (apixaban, rivaroxaban, edoxaban) as effective and often preferred options for cancer-associated thrombosis in appropriately selected patients, alongside LMWH, moving away from LMWH as the unconditional default.', 1),
('de000000-0000-0000-0000-000000000032', 'LMWH remains preferred in patients with luminal gastrointestinal or genitourinary cancers at high bleeding risk, significant drug interactions with DOACs, or an inability to tolerate oral medication.', 2),
('de000000-0000-0000-0000-000000000032', 'Anticoagulant choice in cancer-associated thrombosis should consider bleeding risk, cancer type/location, potential drug interactions with systemic anticancer therapy, and patient preference regarding route of administration.', 3),
('de000000-0000-0000-0000-000000000033', 'In pregnancy with suspected PE, D-dimer is not useful for ruling out PE due to physiological elevation; the diagnostic pathway relies on clinical assessment and imaging (leg ultrasound if DVT is suspected, followed by V/Q scan or CTPA).', 1),
('de000000-0000-0000-0000-000000000033', 'Both V/Q scanning and CTPA are considered acceptable in pregnancy with broadly similar (low) fetal radiation exposure; the choice is often guided by local availability, chest X-ray findings, and maternal radiation dose considerations (CTPA has higher maternal breast radiation dose, V/Q scan has a theoretically higher fetal dose, though both are low).', 2),
('de000000-0000-0000-0000-000000000033', 'A normal chest X-ray does not exclude PE and is typically used mainly to help select and interpret subsequent definitive imaging (e.g. supporting V/Q scan interpretation) rather than as a standalone rule-out test.', 3),
('de000000-0000-0000-0000-000000000034', 'Validated risk stratification tools (PESI, simplified PESI) combined with assessment of RV function and biomarkers help identify low-risk PE patients suitable for safe outpatient management, reducing unnecessary hospital admissions.', 1),
('de000000-0000-0000-0000-000000000034', 'Outpatient PE management still requires confirmed anticoagulation treatment (typically a DOAC), appropriate patient education on red-flag symptoms, and arranged follow-up — it is a site-of-care decision, not a decision to withhold treatment.', 2),
('de000000-0000-0000-0000-000000000034', 'Factors beyond the PE severity score itself (social circumstances, comorbidities, bleeding risk, ability to attend follow-up) must also be considered before committing a patient to outpatient management.', 3),
('de000000-0000-0000-0000-000000000035', 'DOACs can typically be interrupted for surgery based on their predictable pharmacokinetic offset (guided by renal function and procedural bleeding risk) without routine heparin bridging, unlike the traditional bridging approach sometimes used with warfarin.', 1),
('de000000-0000-0000-0000-000000000035', 'The timing of DOAC interruption before surgery depends on the specific drug, renal function, and bleeding risk category of the procedure (standard vs high bleeding risk), with resumption timing similarly individualised post-operatively based on haemostasis and bleeding risk.', 2),
('de000000-0000-0000-0000-000000000035', 'Recent VTE (within the past 1-3 months) increases perioperative thrombotic risk and may warrant closer discussion with haematology regarding optimal timing of interruption and resumption, and occasionally bridging in very high-risk scenarios, but does not usually mandate delaying essential urgent surgery.', 3),
('de000000-0000-0000-0000-000000000036', 'CURB-65 (Confusion, Urea >7 mmol/L, Respiratory rate ≥30/min, Blood pressure systolic <90 or diastolic ≤60 mmHg, Age ≥65) stratifies pneumonia severity and mortality risk, guiding decisions on site of care and antibiotic intensity.', 1),
('de000000-0000-0000-0000-000000000036', 'A CURB-65 score of 3-5 indicates severe pneumonia with high mortality risk, warranting urgent senior review, IV combination antibiotics per local protocol, and consideration of critical care/ICU input.', 2),
('de000000-0000-0000-0000-000000000036', 'Severity scores should complement, not replace, overall clinical assessment, including physiological trends, comorbidities, and response to initial treatment.', 3),
('de000000-0000-0000-0000-000000000037', 'Risk factors for Pseudomonas aeruginosa respiratory infection include structural lung disease (severe COPD, bronchiectasis), recent hospitalisation, recurrent antibiotic exposure, and immunosuppression; these should prompt broader empirical cover pending cultures in appropriate patients.', 1),
('de000000-0000-0000-0000-000000000037', 'Standard CAP empirical regimens (e.g. amoxicillin, co-amoxiclav, macrolides) do not reliably cover Pseudomonas aeruginosa, so antibiotic therapy must be escalated to an antipseudomonal agent once this organism is identified or strongly suspected.', 2),
('de000000-0000-0000-0000-000000000037', 'De-escalation or escalation of antibiotic therapy should always be guided by culture and sensitivity results once available, balancing effective treatment against antimicrobial stewardship principles.', 3),
('de000000-0000-0000-0000-000000000038', 'Legionella pneumonia should be suspected with a history of exposure to contaminated water sources (air conditioning systems, hotels, cruise ships) combined with systemic features such as confusion, diarrhoea, hyponatraemia, and deranged liver function tests alongside pneumonia.', 1),
('de000000-0000-0000-0000-000000000038', 'The Legionella urinary antigen test is rapid and widely used for initial diagnosis but only reliably detects serogroup 1; sputum culture on selective media (BCYE agar) or PCR should be sent in parallel if other serogroups or a negative antigen test with high clinical suspicion are considerations.', 2),
('de000000-0000-0000-0000-000000000038', 'Legionella pneumonia is notifiable and requires specific antibiotic therapy (typically a macrolide or fluoroquinolone) rather than standard first-line CAP antibiotics such as amoxicillin, which have no useful activity against it.', 3),
('de000000-0000-0000-0000-000000000039', 'Pneumocystis jirovecii pneumonia typically presents in advanced HIV (CD4 <200) with subacute breathlessness, dry cough, exertional desaturation, and bilateral perihilar/interstitial infiltrates; raised beta-D-glucan supports the diagnosis though is not specific.', 1),
('de000000-0000-0000-0000-000000000039', 'Adjunctive corticosteroids are indicated in PCP with significant hypoxaemia (room air pO2 <9.3 kPa or SpO2 <92%) as they reduce mortality and respiratory failure risk by dampening the inflammatory response to dying organisms.', 2),
('de000000-0000-0000-0000-000000000039', 'Empirical treatment for PCP should not be delayed for definitive diagnostic confirmation in a clinically compatible high-probability presentation, since organisms remain detectable on respiratory samples for some time after treatment starts.', 3),
('de000000-0000-0000-0000-000000000040', 'Rifampicin resistance on rapid molecular testing (e.g. GeneXpert) is used as a proxy marker for likely MDR-TB and mandates urgent specialist referral, as isoniazid co-resistance frequently accompanies rifampicin resistance.', 1),
('de000000-0000-0000-0000-000000000040', 'MDR-TB management requires an individualised multidrug regimen guided by comprehensive drug susceptibility testing, and should never involve simply adding one drug to a regimen already known to be failing/resistant.', 2),
('de000000-0000-0000-0000-000000000040', 'Infection control (appropriate isolation), public health notification, and contact tracing are essential components of managing confirmed or suspected drug-resistant TB, given the transmission risk of a resistant strain.', 3),
('de000000-0000-0000-0000-000000000041', 'Chronic Pseudomonas aeruginosa colonisation in bronchiectasis with frequent exacerbations is an indication for long-term nebulised antipseudomonal antibiotic therapy (e.g. colistin, tobramycin, gentamicin) to reduce bacterial burden and exacerbation frequency.', 1),
('de000000-0000-0000-0000-000000000041', 'Long-term oral macrolide therapy (azithromycin) is an evidence-based option to reduce exacerbations in bronchiectasis, particularly in patients without Pseudomonas colonisation, but requires baseline exclusion of non-tuberculous mycobacteria and cardiac/hepatic monitoring.', 2),
('de000000-0000-0000-0000-000000000041', 'Non-pharmacological measures (airway clearance techniques, pulmonary rehabilitation) and treatment of the underlying cause where identifiable remain foundational, but pharmacological escalation is appropriate when these alone fail to control frequent exacerbations.', 3),
('de000000-0000-0000-0000-000000000042', 'Antimicrobial stewardship supports de-escalating from broad-spectrum empirical antibiotics to narrow-spectrum, susceptibility-directed therapy once culture results are available and the patient is responding clinically.', 1),
('de000000-0000-0000-0000-000000000042', 'IV-to-oral antibiotic switch criteria typically include clinical improvement, haemodynamic stability, ability to tolerate oral intake, and adequate oral absorption, and should be actively reviewed daily rather than continuing IV therapy by default.', 2),
('de000000-0000-0000-0000-000000000042', 'Bacteraemic pneumococcal pneumonia does not itself mandate broader-spectrum antibiotics if the organism is fully sensitive; treatment choice should be guided by susceptibility results rather than the presence of bacteraemia alone.', 3),
('de000000-0000-0000-0000-000000000043', 'Obesity hypoventilation syndrome is defined by obesity (BMI ≥30) with awake hypercapnia (pCO2 >6 kPa) after excluding other causes of hypoventilation, frequently co-existing with severe OSA.', 1),
('de000000-0000-0000-0000-000000000043', 'Current evidence supports CPAP as adequate initial therapy for many patients with OHS and severe coexisting OSA, with bilevel/NIV reserved for those with inadequate response, more severe hypoventilation, or without predominant OSA.', 2),
('de000000-0000-0000-0000-000000000043', 'Weight loss (including consideration of bariatric surgery in appropriate candidates) is a key long-term management goal in OHS, potentially allowing reduction or cessation of positive airway pressure therapy over time.', 3),
('de000000-0000-0000-0000-000000000044', 'NIV improves survival and quality of life in motor neurone disease patients with symptomatic respiratory muscle weakness and evidence of nocturnal hypoventilation or daytime hypercapnia, and should be offered proactively when these features develop.', 1),
('de000000-0000-0000-0000-000000000044', 'Significant bulbar dysfunction reduces NIV tolerability and effectiveness due to aspiration risk, secretion pooling, and mask-fit difficulties, requiring adjunctive secretion management strategies (cough augmentation, suction) and realistic goals-of-care discussion.', 2),
('de000000-0000-0000-0000-000000000044', 'Decisions about escalation to invasive (tracheostomy) ventilation in MND are complex and should involve early, honest discussion of prognosis, burden, and patient wishes as part of advance care planning, rather than being presented as an automatic next step.', 3),
('de000000-0000-0000-0000-000000000045', 'Excessive sleepiness due to moderate or severe OSA is notifiable to the DVLA, with driving prohibited until symptoms are adequately controlled by treatment; clinicians have a professional responsibility to advise patients of this and document the advice given.', 1),
('de000000-0000-0000-0000-000000000045', 'Group 2 (HGV/bus) licence holders are held to stricter medical standards for OSA than Group 1 (car/motorcycle) licence holders, reflecting the greater public safety risk of commercial driving.', 2),
('de000000-0000-0000-0000-000000000045', 'Effective treatment (typically CPAP) with demonstrated compliance and resolution of excessive sleepiness generally allows safe resumption of driving, subject to DVLA assessment/licensing requirements.', 3),
('de000000-0000-0000-0000-000000000046', 'Cheyne-Stokes respiration/central sleep apnoea in heart failure is characterised by a cyclical crescendo-decrescendo breathing pattern with central apnoeic pauses, reflecting delayed circulatory feedback to respiratory control centres in the context of reduced cardiac output.', 1),
('de000000-0000-0000-0000-000000000046', 'Optimisation of guideline-directed heart failure therapy is the first-line approach to central sleep apnoea/Cheyne-Stokes respiration, as improving cardiac function can reduce or resolve the abnormal breathing pattern.', 2),
('de000000-0000-0000-0000-000000000046', $x$Adaptive servo-ventilation is contraindicated in patients with symptomatic heart failure and LVEF ≤45% following the SERVE-HF trial's finding of increased cardiovascular mortality, an important and frequently tested safety point distinguishing management of central versus obstructive sleep apnoea.$x$, 3),
('de000000-0000-0000-0000-000000000047', 'Suboptimal CPAP adherence is commonly due to mask discomfort, leak, or poor fit, and should prompt active troubleshooting (trying alternative mask types/sizes, humidification, desensitisation support) rather than premature abandonment of CPAP therapy.', 1),
('de000000-0000-0000-0000-000000000047', 'A commonly used adherence benchmark is CPAP usage of at least 4 hours per night on at least 70% of nights, though clinical benefit is generally dose-dependent, and lower usage indicates a need for active support and intervention.', 2),
('de000000-0000-0000-0000-000000000047', 'Alternative treatments for OSA (mandibular advancement devices, positional therapy, upper airway surgery, bariatric surgery) are generally considered after genuine attempts to optimise CPAP tolerance have failed, or in patients with specific contraindications or preferences.', 3),
('de000000-0000-0000-0000-000000000048', 'Severe chest wall restrictive disorders (kyphoscoliosis, neuromuscular disease) causing chronic hypercapnic respiratory failure with nocturnal hypoventilation are a key indication for domiciliary NIV, typically bilevel, which improves symptoms and survival by supporting alveolar ventilation.', 1),
('de000000-0000-0000-0000-000000000048', 'CPAP provides a single fixed airway pressure and does not actively augment ventilation, making bilevel NIV (with separate inspiratory and expiratory pressure settings) the more appropriate modality when the primary problem is hypoventilation rather than upper airway obstruction.', 2),
('de000000-0000-0000-0000-000000000048', 'Oxygen therapy alone is inappropriate as sole treatment for hypoventilatory respiratory failure, since it can mask worsening hypercapnia and further suppress respiratory drive without correcting the underlying ventilatory deficit.', 3),
('de000000-0000-0000-0000-000000000049', 'Sodium oxybate is distinctive among narcolepsy therapies in improving both excessive daytime sleepiness and cataplexy, via consolidation of nocturnal sleep and reduction of REM-intrusion phenomena.', 1),
('de000000-0000-0000-0000-000000000049', 'Modafinil (and other wake-promoting agents) primarily target excessive daytime sleepiness with little direct effect on cataplexy, so additional or alternative therapy is often needed when cataplexy is a prominent, treatment-refractory symptom.', 2),
('de000000-0000-0000-0000-000000000049', 'Narcolepsy type 1 is characterised by hypocretin/orexin deficiency (confirmed by low CSF levels) alongside cataplexy, distinguishing it from narcolepsy type 2, which lacks cataplexy and has normal or only mildly reduced hypocretin levels.', 3),
('de000000-0000-0000-0000-000000000050', 'Persistent hypercapnia 2-4 weeks after an exacerbation requiring acute NIV is an evidence-based indication (HOT-HMV trial) for domiciliary NIV in COPD, reducing readmission risk and improving survival when combined with long-term oxygen therapy.', 1),
('de000000-0000-0000-0000-000000000050', 'Increasing oxygen flow rate in chronically hypercapnic COPD patients risks worsening hypercapnia and should not be used as a strategy to address elevated pCO2; ventilatory support is the appropriate corrective intervention.', 2),
('de000000-0000-0000-0000-000000000050', 'Long-term oxygen therapy and domiciliary NIV address different physiological problems (hypoxaemia versus hypoventilation/hypercapnia respectively) and are frequently used in combination in COPD patients with chronic respiratory failure who have both problems.', 3);
